{"path":"/workspace/backend/httpx.go","command":"create","file_text":"package main

import (
	"encoding/json"
	"io"
	"net/http"
	"strings"
	"time"
)

type apiError struct {
	status int
	code   string
	msg    string
}

func (e *apiError) Error() string { return e.code + ": " + e.msg }

func errJSON(code, msg string, status int) *apiError {
	return &apiError{status: status, code: code, msg: msg}
}

func writeJSON(w http.ResponseWriter, status int, v any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(v)
}

func writeData(w http.ResponseWriter, status int, data any) {
	writeJSON(w, status, map[string]any{"data": data})
}

func writeErr(w http.ResponseWriter, status int, code, msg string) {
	writeJSON(w, status, map[string]string{"error": msg, "code": code})
}

func writeAPIError(w http.ResponseWriter, err error) {
	if e, ok := err.(*apiError); ok {
		writeErr(w, e.status, e.code, e.msg)
		return
	}
	writeErr(w, http.StatusInternalServerError, "internal_error", "internal error")
}

func decodeJSON(r *http.Request, dest any) error {
	body, err := io.ReadAll(io.LimitReader(r.Body, 1<<20))
	if err != nil {
		return errJSON("invalid_json", "invalid json", http.StatusBadRequest)
	}
	if len(strings.TrimSpace(string(body))) == 0 {
		return errJSON("invalid_json", "invalid json", http.StatusBadRequest)
	}
	if err := json.Unmarshal(body, dest); err != nil {
		return errJSON("invalid_json", "invalid json", http.StatusBadRequest)
	}
	return nil
}

func parseTime(s string, code string) (time.Time, error) {
	if s == "" {
		return time.Time{}, errJSON(code, "invalid time", http.StatusBadRequest)
	}
	formats := []string{
		time.RFC3339Nano,
		time.RFC3339,
		"2006-01-02T15:04:05Z07:00",
		"2006-01-02T15:04:05.000Z07:00",
	}
	for _, f := range formats {
		if t, err := time.Parse(f, s); err == nil {
			return t, nil
		}
	}
	return time.Time{}, errJSON(code, "invalid time", http.StatusBadRequest)
}

func requireString(v, field, code string) error {
	if strings.TrimSpace(v) == "" {
		return errJSON(code, field+" is required", http.StatusBadRequest)
	}
	return nil
}

func roleLabel(role string) string {
	switch role {
	case RoleAdministrator:
		return "Administrator"
	case RoleDispatcher:
		return "Dispatcher"
	case RoleRequester:
		return "Requester"
	case RoleCollection:
		return "Certified collection professional"
	case RoleDelivery:
		return "Relay courier"
	case RoleNode:
		return "Node handler"
	case RoleLab:
		return "Laboratory intake operator"
	default:
		return role
	}
}
"}

