{"path":"/workspace/backend/db.go","command":"create","file_text":"package main

import (
	"context"
	"database/sql"
	"fmt"
	"log"
	"os"
	"strings"
	"time"

	_ "github.com/lib/pq"
	"go.mongodb.org/mongo-driver/mongo"
	"go.mongodb.org/mongo-driver/mongo/options"
)

type Store struct {
	PG    *sql.DB
	Mongo *mongo.Client
	Audit *mongo.Collection
}

func openStore() (*Store, error) {
	pgURL := os.Getenv("DATABASE_URL")
	if pgURL == "" {
		pgURL = "postgresql://arena:arena@127.0.0.1:5432/arena?sslmode=disable"
	}
	mongoURL := os.Getenv("MONGODB_URI")
	if mongoURL == "" {
		mongoURL = "mongodb://127.0.0.1:27017/arena"
	}

	var pg *sql.DB
	var err error
	for i := 0; i < 30; i++ {
		pg, err = sql.Open("postgres", pgURL)
		if err == nil {
			if pingErr := pg.Ping(); pingErr == nil {
				err = nil
				break
			} else {
				err = pingErr
			}
		}
		time.Sleep(time.Second)
	}
	if err != nil {
		return nil, fmt.Errorf("postgres: %w", err)
	}
	pg.SetMaxOpenConns(25)
	pg.SetMaxIdleConns(10)

	ctx, cancel := context.WithTimeout(context.Background(), 20*time.Second)
	defer cancel()
	var mc *mongo.Client
	for i := 0; i < 30; i++ {
		mc, err = mongo.Connect(ctx, options.Client().ApplyURI(mongoURL))
		if err == nil {
			if pingErr := mc.Ping(ctx, nil); pingErr == nil {
				err = nil
				break
			} else {
				err = pingErr
			}
		}
		time.Sleep(time.Second)
	}
	if err != nil {
		return nil, fmt.Errorf("mongodb: %w", err)
	}

	dbName := "arena"
	if strings.Contains(mongoURL, "/") {
		parts := strings.Split(mongoURL, "/")
		last := parts[len(parts)-1]
		if q := strings.Index(last, "?"); q >= 0 {
			last = last[:q]
		}
		if last != "" && last != "mongodb:" {
			dbName = last
		}
	}
	return &Store{
		PG:    pg,
		Mongo: mc,
		Audit: mc.Database(dbName).Collection("audit_entries"),
	}, nil
}

func (s *Store) ping(ctx context.Context) error {
	if err := s.PG.PingContext(ctx); err != nil {
		return err
	}
	return s.Mongo.Ping(ctx, nil)
}

func (s *Store) tx(ctx context.Context, fn func(*sql.Tx) error) error {
	tx, err := s.PG.BeginTx(ctx, nil)
	if err != nil {
		return err
	}
	if err := fn(tx); err != nil {
		_ = tx.Rollback()
		return err
	}
	return tx.Commit()
}

func nullStr(ns sql.NullString) string {
	if ns.Valid {
		return ns.String
	}
	return ""
}

func nullTime(nt sql.NullTime) *time.Time {
	if nt.Valid {
		t := nt.Time
		return &t
	}
	return nil
}

func nullFloat(nf sql.NullFloat64) *float64 {
	if nf.Valid {
		v := nf.Float64
		return &v
	}
	return nil
}

func scanStrings(rows *sql.Rows) ([]string, error) {
	defer rows.Close()
	var out []string
	for rows.Next() {
		var s string
		if err := rows.Scan(&s); err != nil {
			return nil, err
		}
		out = append(out, s)
	}
	if out == nil {
		out = []string{}
	}
	return out, rows.Err()
}

func mustEnv(key, fallback string) string {
	if v := os.Getenv(key); v != "" {
		return v
	}
	return fallback
}

func logf(format string, args ...any) {
	log.Printf(format, args...)
}
"}

{"path":"/workspace/backend/auth.go","command":"create","file_text":"package main

import (
	"context"
	"crypto/rand"
	"crypto/sha256"
	"database/sql"
	"encoding/hex"
	"net/http"
	"strings"
	"time"

	"golang.org/x/crypto/bcrypt"
)

type Session struct {
	Token      string
	UserID     string
	Username   string
	FullName   string
	ActiveRole string
	Roles      []string
	Active     bool
	AssignedLoc sql.NullString
}

type ctxKey int

const sessionKey ctxKey = 1

func sessionFrom(ctx context.Context) *Session {
	s, _ := ctx.Value(sessionKey).(*Session)
	return s
}

func hashPassword(pw string) (string, error) {
	b, err := bcrypt.GenerateFromPassword([]byte(pw), bcrypt.DefaultCost)
	return string(b), err
}

func checkPassword(hash, pw string) bool {
	return bcrypt.CompareHashAndPassword([]byte(hash), []byte(pw)) == nil
}

func newToken() string {
	b := make([]byte, 32)
	_, _ = rand.Read(b)
	return hex.EncodeToString(b)
}

func hashIdem(s string) string {
	sum := sha256.Sum256([]byte(s))
	return hex.EncodeToString(sum[:])
}

func (st *Store) loadRoles(ctx context.Context, userID string) ([]string, error) {
	rows, err := st.PG.QueryContext(ctx, `SELECT role FROM user_roles WHERE user_id = $1 ORDER BY role`, userID)
	if err != nil {
		return nil, err
	}
	return scanStrings(rows)
}

func (st *Store) loadSession(ctx context.Context, token string) (*Session, error) {
	var s Session
	s.Token = token
	err := st.PG.QueryRowContext(ctx, `
		SELECT u.user_id, u.username, u.full_name, u.active, s.active_role, u.assigned_location_id
		FROM sessions s JOIN users u ON u.user_id = s.user_id
		WHERE s.token = $1`, token).Scan(&s.UserID, &s.Username, &s.FullName, &s.Active, &s.ActiveRole, &s.AssignedLoc)
	if err == sql.ErrNoRows {
		return nil, errJSON("unauthorized", "unauthorized", http.StatusUnauthorized)
	}
	if err != nil {
		return nil, err
	}
	if !s.Active {
		return nil, errJSON("unauthorized", "unauthorized", http.StatusUnauthorized)
	}
	roles, err := st.loadRoles(ctx, s.UserID)
	if err != nil {
		return nil, err
	}
	s.Roles = roles
	_, _ = st.PG.ExecContext(ctx, `UPDATE sessions SET last_seen_at = now() WHERE token = $1`, token)
	return &s, nil
}

func (st *Store) authMiddleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		header := r.Header.Get("Authorization")
		token := ""
		if strings.HasPrefix(strings.ToLower(header), "bearer ") {
			token = strings.TrimSpace(header[7:])
		}
		if token == "" {
			writeErr(w, http.StatusUnauthorized, "unauthorized", "unauthorized")
			return
		}
		sess, err := st.loadSession(r.Context(), token)
		if err != nil {
			writeAPIError(w, err)
			return
		}
		ctx := context.WithValue(r.Context(), sessionKey, sess)
		next.ServeHTTP(w, r.WithContext(ctx))
	})
}

func (s *Session) hasRole(role string) bool {
	for _, r := range s.Roles {
		if r == role {
			return true
		}
	}
	return false
}

func (s *Session) requireActiveRole(allowed ...string) error {
	if s.ActiveRole == "" {
		return errJSON("role_not_selected", "role not selected", http.StatusConflict)
	}
	if len(allowed) == 0 {
		return nil
	}
	for _, a := range allowed {
		if s.ActiveRole == a {
			return nil
		}
	}
	return errJSON("forbidden", "forbidden", http.StatusForbidden)
}

func (s *Session) requireAny(allowed ...string) error {
	if s.ActiveRole == "" {
		return errJSON("role_not_selected", "role not selected", http.StatusConflict)
	}
	for _, a := range allowed {
		if s.ActiveRole == a {
			return nil
		}
	}
	return errJSON("forbidden", "forbidden", http.StatusForbidden)
}

func (st *Store) ensureAdmin(ctx context.Context) error {
	var n int
	if err := st.PG.QueryRowContext(ctx, `SELECT COUNT(*) FROM users`).Scan(&n); err != nil {
		return err
	}
	if n > 0 {
		return nil
	}
	user := mustEnv("ADMIN_USERNAME", "admin")
	pass := mustEnv("ADMIN_PASSWORD", "admin")
	hash, err := hashPassword(pass)
	if err != nil {
		return err
	}
	id := newUUID()
	_, err = st.PG.ExecContext(ctx, `
		INSERT INTO users (user_id, username, password_hash, full_name, active)
		VALUES ($1, $2, $3, $4, TRUE)`, id, user, hash, "Administrator")
	if err != nil {
		return err
	}
	_, err = st.PG.ExecContext(ctx, `INSERT INTO user_roles (user_id, role) VALUES ($1, $2)`, id, RoleAdministrator)
	return err
}

func bearerFromWS(r *http.Request, protocols []string) string {
	if h := r.Header.Get("Authorization"); strings.HasPrefix(strings.ToLower(h), "bearer ") {
		return strings.TrimSpace(h[7:])
	}
	for _, p := range protocols {
		if strings.HasPrefix(p, "bearer.") {
			// base64url-encoded bearer.<token> — the token after the prefix may itself be the session token
			// Spec: "A bearer [REDACTED] is sent as a base64url-encoded bearer.<token> WebSocket subprotocol."
			rest := strings.TrimPrefix(p, "bearer.")
			if decoded, err := decodeB64URL(rest); err == nil && decoded != "" {
				return decoded
			}
			return rest
		}
	}
	if q := r.URL.Query().Get("token"); q != "" {
		return q
	}
	return ""
}

func decodeB64URL(s string) (string, error) {
	// try raw then padded
	importEnc := func() {}
	_ = importEnc
	b, err := b64RawDecode(s)
	if err != nil {
		return "", err
	}
	return string(b), nil
}
"}

