func (st *Store) writeTimeline(ctx context.Context, tx *sql.Tx, sampleID, journeyID, assignmentID, action, actorID, role, entityType, entityID string, success bool, details map[string]any) (int64, error) {
	if details == nil {
		details = map[string]any{}
	}
	b, _ := json.Marshal(details)
	var eventID int64
	q := `INSERT INTO timeline_events (sample_id, journey_id, assignment_id, action, actor_id, role, entity_type, entity_id, success, occurred_at, details)
	      VALUES (NULLIF($1,'')::uuid, NULLIF($2,'')::uuid, NULLIF($3,'')::uuid, $4, $5, $6, $7, $8, $9, now(), $10) RETURNING event_id`
	var err error
	if tx != nil {
		err = tx.QueryRowContext(ctx, q, sampleID, journeyID, assignmentID, action, actorID, role, entityType, entityID, success, b).Scan(&eventID)
	} else {
		err = st.PG.QueryRowContext(ctx, q, sampleID, journeyID, assignmentID, action, actorID, role, entityType, entityID, success, b).Scan(&eventID)
	}
	return eventID, err
}

func (st *Store) writeAudit(ctx context.Context, actorID, role, action, entityType, entityID string, success bool, details map[string]any) {
	if details == nil {
		details = map[string]any{}
	}
	now := time.Now().UTC()
	id := uuid.NewString()
	doc := bson.M{
		"auditId":    id,
		"audit_id":   id,
		"actorId":    actorID,
		"actor_id":   actorID,
		"role":       role,
		"actorRole":  role,
		"action":     action,
		"entityType": entityType,
		"entity_type": entityType,
		"entityId":   entityID,
		"entity_id":  entityID,
		"success":    success,
		"occurredAt": now,
		"occurred_at": now,
		"details":    details,
	}
	cctx, cancel := context.WithTimeout(ctx, 3*time.Second)
	defer cancel()
	_, _ = st.Audit.InsertOne(cctx, doc)
}

func (st *Store) audit(ctx context.Context, sess *Session, action, entityType, entityID string, success bool, details map[string]any) {
	actor := "system"
	role := ""
	if sess != nil {
		actor = sess.UserID
		role = sess.ActiveRole
	}
	st.writeAudit(ctx, actor, role, action, entityType, entityID, success, details)
	_, _ = st.writeTimeline(ctx, nil, pickSample(entityType, entityID, details), "", "", action, actor, role, entityType, entityID, success, details)
}

func pickSample(entityType, entityID string, details map[string]any) string {
	if entityType == "sample" {
		return entityID
	}
	if details != nil {
		if v, ok := details["sampleId"].(string); ok {
			return v
		}
	}
	return ""
}

func (st *Store) loadTimelineForSample(ctx context.Context, sampleID string) ([]TimelineEntry, error) {
	rows, err := st.PG.QueryContext(ctx, `
		SELECT event_id, action, actor_id, role, entity_type, entity_id, success, occurred_at, details
		FROM timeline_events
		WHERE sample_id = $1 OR entity_id = $1
		ORDER BY event_id ASC`, sampleID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	return scanTimeline(rows)
}

func (st *Store) loadTimelineForEntity(ctx context.Context, entityType, entityID string) ([]TimelineEntry, error) {
	rows, err := st.PG.QueryContext(ctx, `
		SELECT event_id, action, actor_id, role, entity_type, entity_id, success, occurred_at, details
		FROM timeline_events
		WHERE (entity_type = $1 AND entity_id = $2) OR assignment_id::text = $2 OR journey_id::text = $2
		ORDER BY event_id ASC`, entityType, entityID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	return scanTimeline(rows)
}

func scanTimeline(rows *sql.Rows) ([]TimelineEntry, error) {
	out := []TimelineEntry{}
	for rows.Next() {
		var e TimelineEntry
		var details []byte
		var occurred time.Time
		if err := rows.Scan(&e.EventID, &e.Action, &e.ActorID, &e.Role, &e.EntityType, &e.EntityID, &e.Success, &occurred, &details); err != nil {
			return nil, err
		}
		e.OccurredAt = formatTime(occurred)
		e.Details = map[string]any{}
		if len(details) > 0 {
			_ = json.Unmarshal(details, &e.Details)
		}
		out = append(out, e)
	}
	return out, rows.Err()
}

func (st *Store) emitEvent(ctx context.Context, typ, entityType, entityID string, payload map[string]any, audience string) {
	if payload == nil {
		payload = map[string]any{}
	}
	b, _ := json.Marshal(payload)
	_, _ = st.PG.ExecContext(ctx, `
		INSERT INTO realtime_events (type, entity_type, entity_id, payload, audience_role)
		VALUES ($1,$2,$3,$4, NULLIF($5,''))`, typ, entityType, entityID, b, audience)
}

