func (st *Store) handleSearchAudit(w http.ResponseWriter, r *http.Request) {
	sess := sessionFrom(r.Context())
	if err := sess.requireAny(RoleAdministrator, RoleDispatcher); err != nil {
		writeAPIError(w, err)
		return
	}
	var req struct {
		Query      string `json:"query"`
		ActorID    string `json:"actorId"`
		EntityType string `json:"entityType"`
		EntityID   string `json:"entityId"`
		Action     string `json:"action"`
		Role       string `json:"role"`
		Success    *bool  `json:"success"`
		FromTime   string `json:"fromTime"`
		ToTime     string `json:"toTime"`
		Limit      int    `json:"limit"`
		Offset     int    `json:"offset"`
		Order      string `json:"order"`
	}
	if r.Body != nil && r.ContentLength != 0 {
		if err := decodeJSON(r, &req); err != nil {
			writeAPIError(w, err)
			return
		}
	}
	if req.Limit == 0 {
		req.Limit = 500
	}
	if req.Limit < 1 || req.Limit > 5000 {
		writeErr(w, http.StatusBadRequest, "invalid_limit", "invalid limit")
		return
	}
	if req.Offset < 0 {
		writeErr(w, http.StatusBadRequest, "invalid_offset", "invalid offset")
		return
	}
	if req.Order == "" {
		req.Order = "newest_first"
	}
	if req.Order != "newest_first" && req.Order != "oldest_first" {
		writeErr(w, http.StatusBadRequest, "invalid_order", "invalid order")
		return
	}
	filter := bson.M{}
	if req.ActorID != "" {
		filter["actorId"] = req.ActorID
	}
	if req.EntityType != "" {
		filter["entityType"] = req.EntityType
	}
	if req.EntityID != "" {
		filter["entityId"] = req.EntityID
	}
	if req.Action != "" {
		filter["action"] = req.Action
	}
	if req.Role != "" {
		filter["role"] = req.Role
	}
	if req.Success != nil {
		filter["success"] = *req.Success
	}
	timeFilter := bson.M{}
	if req.FromTime != "" {
		t, err := parseTime(req.FromTime, "invalid_time")
		if err != nil {
			writeAPIError(w, err)
			return
		}
		timeFilter["$gte"] = t
	}
	if req.ToTime != "" {
		t, err := parseTime(req.ToTime, "invalid_time")
		if err != nil {
			writeAPIError(w, err)
			return
		}
		timeFilter["$lte"] = t
	}
	if len(timeFilter) > 0 {
		filter["occurredAt"] = timeFilter
	}
	if strings.TrimSpace(req.Query) != "" {
		filter["$or"] = []bson.M{
			{"action": bson.M{"$regex": req.Query, "$options": "i"}},
			{"entityType": bson.M{"$regex": req.Query, "$options": "i"}},
			{"entityId": bson.M{"$regex": req.Query, "$options": "i"}},
			{"role": bson.M{"$regex": req.Query, "$options": "i"}},
			{"actorId": bson.M{"$regex": req.Query, "$options": "i"}},
		}
	}
	ctx := r.Context()
	total, err := st.Audit.CountDocuments(ctx, filter)
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", "internal error")
		return
	}
	sort := bson.D{{Key: "occurredAt", Value: -1}, {Key: "auditId", Value: -1}}
	if req.Order == "oldest_first" {
		sort = bson.D{{Key: "occurredAt", Value: 1}, {Key: "auditId", Value: 1}}
	}
	opts := options.Find().SetSort(sort).SetSkip(int64(req.Offset)).SetLimit(int64(req.Limit))
	cur, err := st.Audit.Find(ctx, filter, opts)
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", "internal error")
		return
	}
	defer cur.Close(ctx)
	entries := []map[string]any{}
	for cur.Next(ctx) {
		var d AuditDoc
		if err := cur.Decode(&d); err != nil {
			continue
		}
		if d.Details == nil {
			d.Details = map[string]any{}
		}
		occurred := d.OccurredAt
		if occurred.IsZero() {
			occurred = d.OccurredAt2
		}
		iso := formatTime(occurred)
		entries = append(entries, map[string]any{
			"auditId":     d.AuditID,
			"audit_id":    d.AuditID,
			"actorId":     d.ActorID,
			"actor_id":    d.ActorID,
			"role":        d.Role,
			"actorRole":   defaultIfEmpty(d.ActorRole, d.Role),
			"action":      d.Action,
			"entityType":  d.EntityType,
			"entity_type": d.EntityType,
			"entityId":    d.EntityID,
			"entity_id":   d.EntityID,
			"success":     d.Success,
			"occurredAt":  iso,
			"occurred_at": iso,
			"details":     d.Details,
		})
	}
	returned := len(entries)
	hasMore := int64(req.Offset+returned) < total
	var nextOffset any
	if hasMore {
		nextOffset = req.Offset + returned
	}
	result := map[string]any{
		"entries":    entries,
		"total":      total,
		"returned":   returned,
		"offset":     req.Offset,
		"limit":      req.Limit,
		"order":      req.Order,
		"hasMore":    hasMore,
		"nextOffset": nextOffset,
	}
	st.audit(ctx, sess, "search_audit_trail", "audit", "", true, map[string]any{"query": req.Query})
	writeData(w, http.StatusOK, result)
}
"}

