func (st *Store) checkIdempotency(ctx context.Context, userID, key, operation, reqHash string) (hit bool, status int, body []byte, err error) {
	if key == "" {
		return false, 0, nil, errJSON("idempotency_required", "idempotency key required", http.StatusBadRequest)
	}
	var storedHash string
	var storedStatus int
	var storedBody []byte
	qerr := st.PG.QueryRowContext(ctx, `
		SELECT request_hash, status_code, response_body FROM idempotency_keys
		WHERE key = $1`, key).Scan(&storedHash, &storedStatus, &storedBody)
	if qerr == sql.ErrNoRows {
		return false, 0, nil, nil
	}
	if qerr != nil {
		return false, 0, nil, qerr
	}
	if storedHash != reqHash {
		return false, 0, nil, errJSON("idempotency_conflict", "idempotency conflict", http.StatusConflict)
	}
	return true, storedStatus, storedBody, nil
}

func (st *Store) saveIdempotency(ctx context.Context, userID, key, operation, reqHash string, status int, data any) {
	b, _ := json.Marshal(map[string]any{"data": data})
	_, _ = st.PG.ExecContext(ctx, `
		INSERT INTO idempotency_keys (key, user_id, operation, request_hash, status_code, response_body)
		VALUES ($1,$2,$3,$4,$5,$6)
		ON CONFLICT (key) DO NOTHING`, key, userID, operation, reqHash, status, b)
}

func replayIdempotent(w http.ResponseWriter, status int, body []byte) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_, _ = w.Write(body)
}

func hashRequest(parts ...string) string {
	return hashIdem(joinParts(parts))
}

func joinParts(parts []string) string {
	out := ""
	for i, p := range parts {
		if i > 0 {
			out += "|"
		}
		out += p
	}
	return out
}
"}

