func (st *Store) handleAuthenticate(w http.ResponseWriter, r *http.Request) {
	var req struct {
		Username string `json:"username"`
		Password string `json:"password"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeAPIError(w, err)
		return
	}
	ctx := r.Context()
	var userID, hash string
	var active bool
	err := st.PG.QueryRowContext(ctx, `SELECT user_id, password_hash, active FROM users WHERE username = $1`, req.Username).
		Scan(&userID, &hash, &active)
	if err == sql.ErrNoRows || !checkPassword(hash, req.Password) || !active {
		st.writeAudit(ctx, "", "", "authenticate_user", "user", req.Username, false, map[string]any{"reason": "invalid_credentials"})
		writeErr(w, http.StatusUnauthorized, "invalid_credentials", "invalid credentials")
		return
	}
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", "internal error")
		return
	}
	roles, err := st.loadRoles(ctx, userID)
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", "internal error")
		return
	}
	token := newToken()
	activeRole := ""
	if len(roles) == 1 {
		activeRole = roles[0]
	}
	_, err = st.PG.ExecContext(ctx, `INSERT INTO sessions (token, user_id, active_role) VALUES ($1,$2,$3)`, token, userID, activeRole)
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", "internal error")
		return
	}
	st.writeAudit(ctx, userID, activeRole, "authenticate_user", "user", userID, true, map[string]any{"username": req.Username})
	_, _ = st.writeTimeline(ctx, nil, "", "", "", "authenticate_user", userID, activeRole, "user", userID, true, map[string]any{"username": req.Username})
	writeData(w, http.StatusOK, map[string]any{
		"sessionToken": token,
		"userId":       userID,
		"roles":        roles,
		"activeRole":   activeRole,
	})
}

