func (st *Store) handleCreateUser(w http.ResponseWriter, r *http.Request) {
	sess := sessionFrom(r.Context())
	if err := sess.requireAny(RoleAdministrator); err != nil {
		writeAPIError(w, err)
		return
	}
	var req struct {
		Username           string          `json:"username"`
		InitialPassword    string          `json:"initialPassword"`
		Email              string          `json:"email"`
		FullName           string          `json:"fullName"`
		Phone              string          `json:"phone"`
		Roles              []string        `json:"roles"`
		Qualifications     []string        `json:"qualifications"`
		Certifications     []Certification `json:"certifications"`
		Active             bool            `json:"active"`
		AssignedLocationID string          `json:"assignedLocationId"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeAPIError(w, err)
		return
	}
	if strings.TrimSpace(req.Username) == "" || req.InitialPassword == "" || len(req.Roles) == 0 {
		writeErr(w, http.StatusBadRequest, "invalid_user", "invalid user")
		return
	}
	for _, role := range req.Roles {
		if !validRole(role) {
			writeErr(w, http.StatusBadRequest, "invalid_user", "invalid role")
			return
		}
	}
	for _, c := range req.Certifications {
		if strings.TrimSpace(c.Code) == "" {
			writeErr(w, http.StatusBadRequest, "invalid_certification", "invalid certification")
			return
		}
	}
	var exists int
	_ = st.PG.QueryRowContext(r.Context(), `SELECT COUNT(*) FROM users WHERE username = $1`, req.Username).Scan(&exists)
	if exists > 0 {
		writeErr(w, http.StatusConflict, "username_exists", "username exists")
		return
	}
	hash, err := hashPassword(req.InitialPassword)
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", "internal error")
		return
	}
	id := newUUID()
	ctx := r.Context()
	err = st.tx(ctx, func(tx *sql.Tx) error {
		var loc any
		if req.AssignedLocationID != "" {
			loc = req.AssignedLocationID
		}
		if _, err := tx.ExecContext(ctx, `
			INSERT INTO users (user_id, username, password_hash, email, full_name, phone, active, assigned_location_id)
			VALUES ($1,$2,$3,$4,$5,$6,$7,$8)`,
			id, req.Username, hash, req.Email, req.FullName, req.Phone, req.Active, loc); err != nil {
			return err
		}
		for _, role := range uniqStrings(req.Roles) {
			if _, err := tx.ExecContext(ctx, `INSERT INTO user_roles (user_id, role) VALUES ($1,$2)`, id, role); err != nil {
				return err
			}
		}
		for _, q := range uniqStrings(req.Qualifications) {
			if _, err := tx.ExecContext(ctx, `INSERT INTO user_qualifications (user_id, qualification) VALUES ($1,$2)`, id, q); err != nil {
				return err
			}
		}
		for _, c := range req.Certifications {
			var exp any
			if c.ExpiresAt != nil && *c.ExpiresAt != "" {
				t, err := parseTime(*c.ExpiresAt, "invalid_certification")
				if err != nil {
					return err
				}
				exp = t
			}
			if _, err := tx.ExecContext(ctx, `
				INSERT INTO user_certifications (user_id, code, active, expires_at) VALUES ($1,$2,$3,$4)`,
				id, c.Code, c.Active, exp); err != nil {
				return err
			}
		}
		return nil
	})
	if err != nil {
		if e, ok := err.(*apiError); ok {
			writeAPIError(w, e)
			return
		}
		writeErr(w, http.StatusInternalServerError, "internal_error", "internal error")
		return
	}
	data, _ := st.userPayload(ctx, id)
	st.audit(ctx, sess, "create_user", "user", id, true, map[string]any{"username": req.Username})
	writeData(w, http.StatusCreated, data)
}

func (st *Store) handleUpdateUserAccess(w http.ResponseWriter, r *http.Request) {
	sess := sessionFrom(r.Context())
	if err := sess.requireAny(RoleAdministrator); err != nil {
		writeAPIError(w, err)
		return
	}
	var req struct {
		UserID             string          `json:"userId"`
		Roles              []string        `json:"roles"`
		Qualifications     []string        `json:"qualifications"`
		Certifications     []Certification `json:"certifications"`
		Active             bool            `json:"active"`
		AssignedLocationID string          `json:"assignedLocationId"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeAPIError(w, err)
		return
	}
	for _, role := range req.Roles {
		if !validRole(role) {
			writeErr(w, http.StatusBadRequest, "invalid_json", "invalid role")
			return
		}
	}
	for _, c := range req.Certifications {
		if strings.TrimSpace(c.Code) == "" {
			writeErr(w, http.StatusBadRequest, "invalid_certification", "invalid certification")
			return
		}
	}
	ctx := r.Context()
	var exists int
	_ = st.PG.QueryRowContext(ctx, `SELECT COUNT(*) FROM users WHERE user_id = $1`, req.UserID).Scan(&exists)
	if exists == 0 {
		writeErr(w, http.StatusNotFound, "not_found", "not found")
		return
	}
	err := st.tx(ctx, func(tx *sql.Tx) error {
		var loc any
		if req.AssignedLocationID != "" {
			loc = req.AssignedLocationID
		}
		if _, err := tx.ExecContext(ctx, `UPDATE users SET active = $1, assigned_location_id = $2 WHERE user_id = $3`, req.Active, loc, req.UserID); err != nil {
			return err
		}
		if _, err := tx.ExecContext(ctx, `DELETE FROM user_roles WHERE user_id = $1`, req.UserID); err != nil {
			return err
		}
		for _, role := range uniqStrings(req.Roles) {
			if _, err := tx.ExecContext(ctx, `INSERT INTO user_roles (user_id, role) VALUES ($1,$2)`, req.UserID, role); err != nil {
				return err
			}
		}
		if req.Qualifications != nil {
			if _, err := tx.ExecContext(ctx, `DELETE FROM user_qualifications WHERE user_id = $1`, req.UserID); err != nil {
				return err
			}
			for _, q := range uniqStrings(req.Qualifications) {
				if _, err := tx.ExecContext(ctx, `INSERT INTO user_qualifications (user_id, qualification) VALUES ($1,$2)`, req.UserID, q); err != nil {
					return err
				}
			}
		}
		if req.Certifications != nil {
			if _, err := tx.ExecContext(ctx, `DELETE FROM user_certifications WHERE user_id = $1`, req.UserID); err != nil {
				return err
			}
			for _, c := range req.Certifications {
				var exp any
				if c.ExpiresAt != nil && *c.ExpiresAt != "" {
					t, err := parseTime(*c.ExpiresAt, "invalid_certification")
					if err != nil {
						return err
					}
					exp = t
				}
				if _, err := tx.ExecContext(ctx, `
					INSERT INTO user_certifications (user_id, code, active, expires_at) VALUES ($1,$2,$3,$4)`,
					req.UserID, c.Code, c.Active, exp); err != nil {
					return err
				}
			}
		}
		return nil
	})
	if err != nil {
		if e, ok := err.(*apiError); ok {
			writeAPIError(w, e)
			return
		}
		writeErr(w, http.StatusInternalServerError, "internal_error", "internal error")
		return
	}
	data, _ := st.userPayload(ctx, req.UserID)
	st.audit(ctx, sess, "update_user_access", "user", req.UserID, true, nil)
	writeData(w, http.StatusCreated, data)
}

