func (st *Store) userPayload(ctx context.Context, userID string) (map[string]any, error) {
	var username, email, fullName, phone string
	var active bool
	err := st.PG.QueryRowContext(ctx, `
		SELECT username, email, full_name, phone, active FROM users WHERE user_id = $1`, userID).
		Scan(&username, &email, &fullName, &phone, &active)
	if err != nil {
		return nil, err
	}
	roles, _ := st.loadRoles(ctx, userID)
	quals := []string{}
	rows, err := st.PG.QueryContext(ctx, `SELECT qualification FROM user_qualifications WHERE user_id = $1`, userID)
	if err == nil {
		quals, _ = scanStrings(rows)
	}
	certs := []Certification{}
	crows, err := st.PG.QueryContext(ctx, `SELECT code, active, expires_at FROM user_certifications WHERE user_id = $1`, userID)
	if err == nil {
		defer crows.Close()
		for crows.Next() {
			var c Certification
			var exp sql.NullTime
			if err := crows.Scan(&c.Code, &c.Active, &exp); err == nil {
				if exp.Valid {
					s := formatTime(exp.Time)
					c.ExpiresAt = &s
				}
				certs = append(certs, c)
			}
		}
	}
	return map[string]any{
		"userId":         userID,
		"username":       username,
		"email":          email,
		"fullName":       fullName,
		"phone":          phone,
		"roles":          roles,
		"qualifications": quals,
		"certifications": certs,
		"active":         active,
	}, nil
}

