func (st *Store) handleRecordWorkerLocation(w http.ResponseWriter, r *http.Request) {
	sess := sessionFrom(r.Context())
	if err := sess.requireAny(RoleCollection, RoleDelivery, RoleNode, RoleLab, RoleAdministrator, RoleDispatcher); err != nil {
		writeAPIError(w, err)
		return
	}
	var req struct {
		AssignmentID string     `json:"assignmentId"`
		Coordinate   Coordinate `json:"coordinate"`
		Sequence     int        `json:"sequence"`
		RecordedAt   string     `json:"recordedAt"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeAPIError(w, err)
		return
	}
	if !validCoord(req.Coordinate) {
		writeErr(w, http.StatusBadRequest, "invalid_coordinate", "invalid coordinate")
		return
	}
	if req.Sequence < 1 {
		writeErr(w, http.StatusBadRequest, "invalid_sequence", "invalid sequence")
		return
	}
	recordedAt, err := parseTime(req.RecordedAt, "invalid_time")
	if err != nil {
		writeAPIError(w, err)
		return
	}
	ctx := r.Context()
	var exists int
	_ = st.PG.QueryRowContext(ctx, `SELECT COUNT(*) FROM assignments WHERE assignment_id = $1`, req.AssignmentID).Scan(&exists)
	if exists == 0 {
		writeErr(w, http.StatusNotFound, "not_found", "not found")
		return
	}
	var curSeq int
	_ = st.PG.QueryRowContext(ctx, `SELECT location_sequence FROM users WHERE user_id = $1`, sess.UserID).Scan(&curSeq)
	if req.Sequence <= curSeq {
		writeErr(w, http.StatusConflict, "stale_location", "stale location")
		return
	}
	_, err = st.PG.ExecContext(ctx, `
		INSERT INTO worker_locations (worker_id, assignment_id, latitude, longitude, sequence, recorded_at)
		VALUES ($1,$2,$3,$4,$5,$6)`,
		sess.UserID, req.AssignmentID, req.Coordinate.Latitude, req.Coordinate.Longitude, req.Sequence, recordedAt)
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", "internal error")
		return
	}
	_, _ = st.PG.ExecContext(ctx, `
		UPDATE users SET latest_lat = $1, latest_lng = $2, location_recorded_at = $3, location_sequence = $4
		WHERE user_id = $5`,
		req.Coordinate.Latitude, req.Coordinate.Longitude, recordedAt, req.Sequence, sess.UserID)
	// propagate to samples currently held by this worker
	_, _ = st.PG.ExecContext(ctx, `
		UPDATE samples SET latest_lat = $1, latest_lng = $2, location_recorded_at = $3
		WHERE current_holder_id = $4`,
		req.Coordinate.Latitude, req.Coordinate.Longitude, recordedAt, sess.UserID)
	st.audit(ctx, sess, "record_worker_location", "assignment", req.AssignmentID, true, map[string]any{
		"coordinate": req.Coordinate, "sequence": req.Sequence,
	})
	st.emitEvent(ctx, "worker_location", "worker", sess.UserID, map[string]any{
		"assignmentId": req.AssignmentID, "coordinate": req.Coordinate,
	}, "")
	writeData(w, http.StatusCreated, map[string]any{
		"assignmentId": req.AssignmentID,
		"coordinate":   req.Coordinate,
		"sequence":     req.Sequence,
		"recordedAt":   formatTime(recordedAt),
	})
}

