func (st *Store) handleBootstrap(w http.ResponseWriter, r *http.Request) {
	sess := sessionFrom(r.Context())
	now := time.Now().UTC()
	user := map[string]any{
		"userId":                 sess.UserID,
		"username":               sess.Username,
		"fullName":               sess.FullName,
		"roles":                  sess.Roles,
		"activeRole":             sess.ActiveRole,
		"roleSelectionRequired":  sess.ActiveRole == "" && len(sess.Roles) > 1,
	}
	data := map[string]any{
		"user":       user,
		"serverTime": formatTime(now),
	}
	if sess.ActiveRole == RoleRequester || containsStr(sess.Roles, RoleRequester) {
		samples, _ := st.listRequesterSamples(r.Context(), sess.UserID)
		data["requesterSamples"] = samples
	}
	if isAdminOrDispatcher(sess.ActiveRole) {
		ops, _ := st.buildOperationsState(r.Context(), "")
		data["operations"] = ops
	}
	writeData(w, http.StatusOK, data)
}

func (st *Store) listRequesterSamples(ctx context.Context, requesterID string) ([]map[string]any, error) {
	rows, err := st.PG.QueryContext(ctx, `
		SELECT s.sample_id, s.request_id, s.status, s.serviceability, s.target_laboratory_id,
		       r.requested_at, r.delivery_deadline
		FROM samples s JOIN collection_requests r ON r.request_id = s.request_id
		WHERE s.requester_id = $1
		ORDER BY r.created_at DESC`, requesterID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	out := []map[string]any{}
	for rows.Next() {
		var sampleID, requestID, status, svc string
		var lab sql.NullString
		var requested, deadline time.Time
		if err := rows.Scan(&sampleID, &requestID, &status, &svc, &lab, &requested, &deadline); err != nil {
			continue
		}
		out = append(out, map[string]any{
			"sampleId":            sampleID,
			"requestId":           requestID,
			"status":              status,
			"serviceability":      svc,
			"targetLaboratoryId":  nullStr(lab),
			"requestedAt":         formatTime(requested),
			"deliveryDeadline":    formatTime(deadline),
		})
	}
	return out, nil
}

func (st *Store) handleEvents(w http.ResponseWriter, r *http.Request) {
	sess := sessionFrom(r.Context())
	since := int64(0)
	if q := r.URL.Query().Get("since"); q != "" {
		var n int64
		if _, err := parseInt64(q, &n); err == nil {
			since = n
		}
	}
	upgrade := strings.Contains(strings.ToLower(r.Header.Get("Upgrade")), "websocket")
	if upgrade {
		st.handleWSEvents(w, r, sess, since)
		return
	}
	ctx := r.Context()
	rows, err := st.PG.QueryContext(ctx, `
		SELECT id, type, entity_type, entity_id, payload, created_at, audience_role
		FROM realtime_events
		WHERE id > $1
		  AND (audience_role IS NULL OR audience_role = $2)
		ORDER BY id ASC
		LIMIT 500`, since, sess.ActiveRole)
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", "internal error")
		return
	}
	defer rows.Close()
	events := []map[string]any{}
	var cursor int64 = since
	for rows.Next() {
		var id int64
		var typ, et, eid string
		var payload []byte
		var created time.Time
		var aud sql.NullString
		if err := rows.Scan(&id, &typ, &et, &eid, &payload, &created, &aud); err != nil {
			continue
		}
		var p map[string]any
		_ = json.Unmarshal(payload, &p)
		if p == nil {
			p = map[string]any{}
		}
		events = append(events, map[string]any{
			"id":         id,
			"type":       typ,
			"entityType": et,
			"entityId":   eid,
			"payload":    p,
			"createdAt":  formatTime(created),
		})
		cursor = id
	}
	writeData(w, http.StatusOK, map[string]any{"events": events, "cursor": cursor})
}

func parseInt64(s string, dest *int64) (int, error) {
	var n int64
	for _, c := range s {
		if c < '0' || c > '9' {
			return 0, errJSON("invalid_json", "invalid", 400)
		}
		n = n*10 + int64(c-'0')
	}
	*dest = n
	return 0, nil
}
