func (st *Store) handleConfigureCapacity(w http.ResponseWriter, r *http.Request) {
	sess := sessionFrom(r.Context())
	if err := sess.requireAny(RoleAdministrator, RoleDispatcher, RoleNode, RoleLab); err != nil {
		writeAPIError(w, err)
		return
	}
	var req struct {
		ResourceID          string `json:"resourceId"`
		CapacityUnits       int    `json:"capacityUnits"`
		CooledCapacityUnits *int   `json:"cooledCapacityUnits"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeAPIError(w, err)
		return
	}
	if req.CapacityUnits < 0 {
		writeErr(w, http.StatusBadRequest, "invalid_capacity", "invalid capacity")
		return
	}
	cooled := 0
	if req.CooledCapacityUnits != nil {
		if *req.CooledCapacityUnits < 0 {
			writeErr(w, http.StatusBadRequest, "invalid_capacity", "invalid capacity")
			return
		}
		cooled = *req.CooledCapacityUnits
	}
	ctx := r.Context()
	// node/lab workers may only configure their assigned location
	if sess.ActiveRole == RoleNode || sess.ActiveRole == RoleLab {
		if !sess.AssignedLoc.Valid || sess.AssignedLoc.String != req.ResourceID {
			writeErr(w, http.StatusForbidden, "forbidden", "forbidden")
			return
		}
	}
	var reserved, cooledReserved int
	err := st.PG.QueryRowContext(ctx, `
		SELECT reserved_units, cooled_reserved_units FROM capacity_pools WHERE resource_id = $1`, req.ResourceID).
		Scan(&reserved, &cooledReserved)
	if err == sql.ErrNoRows {
		_, _ = st.PG.ExecContext(ctx, `
			INSERT INTO capacity_pools (resource_id, resource_kind, capacity_units, cooled_capacity_units)
			VALUES ($1, 'unknown', $2, $3)`, req.ResourceID, req.CapacityUnits, cooled)
	} else if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", "internal error")
		return
	} else {
		if req.CapacityUnits < reserved || cooled < cooledReserved {
			writeErr(w, http.StatusConflict, "capacity_reserved", "capacity reserved")
			return
		}
		_, err = st.PG.ExecContext(ctx, `
			UPDATE capacity_pools SET capacity_units = $1, cooled_capacity_units = $2 WHERE resource_id = $3`,
			req.CapacityUnits, cooled, req.ResourceID)
		if err != nil {
			writeErr(w, http.StatusInternalServerError, "internal_error", "internal error")
			return
		}
	}
	st.bumpNetwork(ctx, nil)
	st.audit(ctx, sess, "configure_capacity", "capacity", req.ResourceID, true, map[string]any{
		"capacityUnits": req.CapacityUnits, "cooledCapacityUnits": cooled,
	})
	writeData(w, http.StatusOK, map[string]any{
		"resourceId":          req.ResourceID,
		"capacityUnits":       req.CapacityUnits,
		"cooledCapacityUnits": cooled,
	})
}

