	}
	if req.Name == "" || req.ContainerType == "" || req.TemperatureMinC > req.TemperatureMaxC {
		writeErr(w, http.StatusBadRequest, "invalid_handling_rule", "invalid handling rule")
		return
	}
	qreq := true
	if req.QualifiedCollectorRequired != nil {
		qreq = *req.QualifiedCollectorRequired
	}
	cooled := false
	if req.RequiresCooledRoute != nil {
		cooled = *req.RequiresCooledRoute
	}
	batch := true
	if req.BatchingAllowed != nil {
		batch = *req.BatchingAllowed
	}
