func (st *Store) reserveCapacity(ctx context.Context, tx *sql.Tx, resourceID, journeyID, sampleID string, cooled bool, units int) error {
	var capu, resu, ccap, cres int
	err := tx.QueryRowContext(ctx, `
		SELECT capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units
		FROM capacity_pools WHERE resource_id = $1 FOR UPDATE`, resourceID).
		Scan(&capu, &resu, &ccap, &cres)
	if err == sql.ErrNoRows {
		// unlimited if not configured
		_, _ = tx.ExecContext(ctx, `
			INSERT INTO capacity_reservations (resource_id, journey_id, sample_id, cooled, units, active)
			VALUES ($1,$2,$3,$4,$5,TRUE)`, resourceID, journeyID, sampleID, cooled, units)
		return nil
	}
	if err != nil {
		return err
	}
	if cooled {
		if ccap > 0 && cres+units > ccap {
			return errJSON("cooled_capacity_exhausted", "cooled capacity exhausted", http.StatusConflict)
		}
		_, err = tx.ExecContext(ctx, `UPDATE capacity_pools SET cooled_reserved_units = cooled_reserved_units + $1 WHERE resource_id = $2`, units, resourceID)
	} else {
		if capu > 0 && resu+units > capu {
			return errJSON("capacity_exhausted", "capacity exhausted", http.StatusConflict)
		}
		_, err = tx.ExecContext(ctx, `UPDATE capacity_pools SET reserved_units = reserved_units + $1 WHERE resource_id = $2`, units, resourceID)
	}
	if err != nil {
		return err
	}
	_, err = tx.ExecContext(ctx, `
		INSERT INTO capacity_reservations (resource_id, journey_id, sample_id, cooled, units, active)
		VALUES ($1,$2,$3,$4,$5,TRUE)`, resourceID, journeyID, sampleID, cooled, units)
	return err
}

func (st *Store) releaseJourneyCapacity(ctx context.Context, tx *sql.Tx, journeyID string) {
	rows, err := tx.QueryContext(ctx, `
		SELECT reservation_id, resource_id, cooled, units FROM capacity_reservations
		WHERE journey_id = $1 AND active = TRUE`, journeyID)
	if err != nil {
		return
	}
	type resv struct {
		id, resource string
		cooled       bool
		units        int
	}
	var list []resv
	for rows.Next() {
		var r resv
		if err := rows.Scan(&r.id, &r.resource, &r.cooled, &r.units); err == nil {
			list = append(list, r)
		}
	}
	rows.Close()
	for _, r := range list {
		if r.cooled {
			_, _ = tx.ExecContext(ctx, `UPDATE capacity_pools SET cooled_reserved_units = GREATEST(cooled_reserved_units - $1, 0) WHERE resource_id = $2`, r.units, r.resource)
		} else {
			_, _ = tx.ExecContext(ctx, `UPDATE capacity_pools SET reserved_units = GREATEST(reserved_units - $1, 0) WHERE resource_id = $2`, r.units, r.resource)
		}
		_, _ = tx.ExecContext(ctx, `UPDATE capacity_reservations SET active = FALSE WHERE reservation_id = $1`, r.id)
	}
}

func (st *Store) handleReadServiceabilitySnapshot(w http.ResponseWriter, r *http.Request) {
	sess := sessionFrom(r.Context())
	if err := sess.requireActiveRole(); err != nil {
		writeAPIError(w, err)
		return
	}
	if r.Body != nil && r.ContentLength > 0 {
		var dummy map[string]any
		if err := decodeJSON(r, &dummy); err != nil {
			writeAPIError(w, err)
			return
		}
	}
	snap, err := st.latestSnapshot(r.Context())
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", "internal error")
		return
	}
	writeData(w, http.StatusOK, snap)
}

func (st *Store) latestSnapshot(ctx context.Context) (map[string]any, error) {
	var version, revision int
	var status string
	var computed time.Time
	var payload []byte
	err := st.PG.QueryRowContext(ctx, `
		SELECT version, status, computed_at, network_revision, payload
		FROM serviceability_snapshots ORDER BY version DESC LIMIT 1`).
		Scan(&version, &status, &computed, &revision, &payload)
	if err != nil {
		return nil, err
	}
	var p struct {
		Regions                    []map[string]any `json:"regions"`
		ActiveCollectionPointCount int              `json:"activeCollectionPointCount"`
	}
	_ = json.Unmarshal(payload, &p)
	if p.Regions == nil {
		p.Regions = []map[string]any{}
	}
	return map[string]any{
		"version":                    version,
		"status":                     "complete",
		"computedAt":                 formatTime(computed),
		"networkRevision":            revision,
		"regions":                    p.Regions,
		"activeCollectionPointCount": p.ActiveCollectionPointCount,
	}, nil
}
