func (st *Store) loadSampleType(ctx context.Context, id string) (*sampleTypeRow, error) {
	var t sampleTypeRow
	err := st.PG.QueryRowContext(ctx, `
		SELECT sample_type_id, name, qualified_collector_required, required_qualification,
		       container_type, temperature_min_c, temperature_max_c, requires_cooled_route, batching_allowed
		FROM sample_types WHERE sample_type_id = $1`, id).
		Scan(&t.ID, &t.Name, &t.QualRequired, &t.RequiredQual, &t.Container, &t.TempMin, &t.TempMax, &t.RequiresCooled, &t.BatchingAllowed)
	if err != nil {
		return nil, err
	}
	t.Incompatible, _ = st.loadIncompat(ctx, id)
	return &t, nil
}

func (st *Store) acceptingLabs(ctx context.Context, typeID string) (map[string]bool, error) {
	rows, err := st.PG.QueryContext(ctx, `
		SELECT laboratory_id FROM laboratory_acceptance WHERE sample_type_id = $1 AND accepts = TRUE`, typeID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	out := map[string]bool{}
	for rows.Next() {
		var id string
		if err := rows.Scan(&id); err == nil {
			out[id] = true
		}
	}
	return out, nil
}

func (st *Store) recomputeServiceability(ctx context.Context) {
	locs, err := st.loadLocations(ctx)
	if err != nil {
		return
	}
	var revision int
	_ = st.PG.QueryRowContext(ctx, `SELECT value::int FROM app_meta WHERE key = 'network_revision'`).Scan(&revision)
	regions := []map[string]any{}
	count := 0
	for _, l := range locs {
		if l.Active && l.Collection {
			count++
			regions = append(regions, map[string]any{
				"locationId": l.ID,
				"name":       l.Name,
				"latitude":   l.Lat,
				"longitude":  l.Lng,
				"coverageKm": l.Coverage,
			})
		}
	}
	payload, _ := json.Marshal(map[string]any{
		"regions":                    regions,
		"activeCollectionPointCount": count,
	})
	var last int
	_ = st.PG.QueryRowContext(ctx, `SELECT COALESCE(MAX(version),0) FROM serviceability_snapshots`).Scan(&last)
	_, _ = st.PG.ExecContext(ctx, `
		INSERT INTO serviceability_snapshots (version, status, computed_at, network_revision, payload)
		VALUES ($1, 'complete', now(), $2, $3)`, last+1, revision, payload)
	_, _ = st.PG.ExecContext(ctx, `UPDATE app_meta SET value = $1 WHERE key = 'serviceability_version'`, last+1)
}

func (st *Store) findRoute(ctx context.Context, originLat, originLng float64, originType, originNodeID, typeID string, needsCooled bool, deadline time.Time, earliest time.Time) (*plannedRoute, string) {
	locs, err := st.loadLocations(ctx)
	if err != nil {
		return nil, "no_route"
	}
	conns, err := st.loadConnections(ctx)
	if err != nil {
		return nil, "no_route"
	}
	locByID := map[string]locRow{}
	for _, l := range locs {
		locByID[l.ID] = l
	}
	accept, _ := st.acceptingLabs(ctx, typeID)
	labs := []locRow{}
	for _, l := range locs {
		if l.Active && l.Laboratory && accept[l.ID] {
			labs = append(labs, l)
		}
	}
	if len(labs) == 0 {
		return nil, "no_accepting_laboratory"
	}

	// determine start nodes
	startNodes := []locRow{}
	if originType == OriginNode && originNodeID != "" {
		if l, ok := locByID[originNodeID]; ok && l.Active {
			startNodes = append(startNodes, l)
		}
	} else {
		for _, l := range locs {
			if !l.Active || !l.Collection {
				continue
			}
			d := haversineKm(originLat, originLng, l.Lat, l.Lng)
			if d <= l.Coverage && d <= 5.0 {
				startNodes = append(startNodes, l)
			}
		}
	}
	if len(startNodes) == 0 {
		return nil, "outside_service_coverage"
	}

	// graph of active connections (optionally requiring cooled)
	type edge struct {
		to      string
		minutes int
		cost    float64
		connID  string
		cooled  bool
	}
	graph := map[string][]edge{}
	for _, c := range conns {
		if !c.Active {
			continue
		}
		if needsCooled && !c.Cooled {
			continue
		}
		from := locByID[c.FromID]
		to := locByID[c.ToID]
		if !from.Active || !to.Active {
			continue
		}
		graph[c.FromID] = append(graph[c.FromID], edge{to: c.ToID, minutes: c.TravelMinutes, cost: c.Cost, connID: c.ID, cooled: c.Cooled})
	}

	// Dijkstra-like by minutes then cost
	type state struct {
		node    string
		minutes int
		cost    float64
		path    []routeHop
	}
	best := (*plannedRoute)(nil)
	for _, start := range startNodes {
		// if start itself is an accepting lab, zero-hop route
		if accept[start.ID] && start.Laboratory {
			cand := &plannedRoute{
				CollectionNode: start.ID,
				Laboratory:     start.ID,
				Hops:           []routeHop{},
				TotalMinutes:   start.Handling,
				TotalCost:      0,
				NeedsCooled:    needsCooled,
			}
			if best == nil || cand.TotalMinutes < best.TotalMinutes || (cand.TotalMinutes == best.TotalMinutes && cand.TotalCost < best.TotalCost) {
				best = cand
			}
		}
		seen := map[string]int{}
		queue := []state{{node: start.ID, minutes: start.Handling, cost: 0}}
		for len(queue) > 0 {
			// pop min minutes
			mi := 0
			for i := 1; i < len(queue); i++ {
				if queue[i].minutes < queue[mi].minutes || (queue[i].minutes == queue[mi].minutes && queue[i].cost < queue[mi].cost) {
					mi = i
				}
			}
			cur := queue[mi]
			queue = append(queue[:mi], queue[mi+1:]...)
			if prev, ok := seen[cur.node]; ok && prev <= cur.minutes {
				continue
			}
			seen[cur.node] = cur.minutes
			if accept[cur.node] && locByID[cur.node].Laboratory {
				cand := &plannedRoute{
					CollectionNode: start.ID,
					Laboratory:     cur.node,
					Hops:           append([]routeHop{}, cur.path...),
					TotalMinutes:   cur.minutes + locByID[cur.node].Handling,
					TotalCost:      cur.cost,
					NeedsCooled:    needsCooled,
				}
				if best == nil || cand.TotalMinutes < best.TotalMinutes || (cand.TotalMinutes == best.TotalMinutes && cand.TotalCost < best.TotalCost) {
					best = cand
				}
			}
			for _, e := range graph[cur.node] {
				hop := routeHop{FromID: cur.node, ToID: e.to, ConnID: e.connID, Minutes: e.minutes, Cost: e.cost, Cooled: e.cooled}
				np := append(append([]routeHop{}, cur.path...), hop)
				queue = append(queue, state{node: e.to, minutes: cur.minutes + e.minutes + locByID[e.to].Handling, cost: cur.cost + e.cost, path: np})
			}
		}
	}
	if best == nil {
		return nil, "no_route"
	}
	// deadline check
	if !deadline.IsZero() && !earliest.IsZero() {
		eta := earliest.Add(time.Duration(best.TotalMinutes) * time.Minute)
		if eta.After(deadline) {
			return nil, "deadline_unreachable"
		}
	}
	return best, "serviceable"
}

func (st *Store) checkCapacityForRoute(ctx context.Context, route *plannedRoute, cooled bool) bool {
	if route == nil {
		return false
	}
	check := func(id string) bool {
		c := st.getCapacity(ctx, id)
		if cooled {
			if c.CooledCapacityUnits > 0 && c.CooledAvailableUnits < 1 {
				return false
			}
		} else {
			if c.CapacityUnits > 0 && c.AvailableUnits < 1 {
				return false
			}
		}
		return true
	}
	if !check(route.CollectionNode) {
		return false
	}
	if !check(route.Laboratory) {
		return false
	}
	for _, h := range route.Hops {
		if !check(h.ConnID) {
			return false
		}
	}
	return true
}

type svcResult struct {
	Serviceable           bool
	Reason                string
	TargetLaboratoryID    string
	EstimatedArrivalAt    time.Time
	ServiceabilityVersion int
	Route                 *plannedRoute
}

func (st *Store) evaluateServiceability(ctx context.Context, origin Coordinate, originType, originNodeID, typeID string, requestedAt, deadline, earliest, latest time.Time) (*svcResult, error) {
	styp, err := st.loadSampleType(ctx, typeID)
	if err != nil {
		return nil, errJSON("not_found", "sample type not found", http.StatusNotFound)
	}
	var version int
	_ = st.PG.QueryRowContext(ctx, `SELECT COALESCE(MAX(version),1) FROM serviceability_snapshots`).Scan(&version)
	needsCooled := styp.RequiresCooled
	route, reason := st.findRoute(ctx, origin.Latitude, origin.Longitude, originType, originNodeID, typeID, needsCooled, deadline, earliest)
	res := &svcResult{Reason: reason, ServiceabilityVersion: version, Route: route}
	if reason != "serviceable" {
		res.Serviceable = false
		return res, nil
	}
	if !st.checkCapacityForRoute(ctx, route, needsCooled) {
		res.Serviceable = false
		res.Reason = "insufficient_capacity"
		return res, nil
	}
	res.Serviceable = true
	res.TargetLaboratoryID = route.Laboratory
	res.EstimatedArrivalAt = earliest.Add(time.Duration(route.TotalMinutes) * time.Minute)
	return res, nil
}

func (st *Store) handleCheckServiceability(w http.ResponseWriter, r *http.Request) {
	sess := sessionFrom(r.Context())
	if err := sess.requireAny(RoleRequester, RoleAdministrator, RoleDispatcher); err != nil {
		writeAPIError(w, err)
		return
	}
	var req struct {
		Origin               Coordinate `json:"origin"`
		OriginType           string     `json:"originType"`
		OriginNodeID         string     `json:"originNodeId"`
		SampleTypeID         string     `json:"sampleTypeId"`
		RequestedAt          string     `json:"requestedAt"`
		DeliveryDeadline     string     `json:"deliveryDeadline"`
		EarliestCollectionAt string     `json:"earliestCollectionAt"`
		LatestCollectionAt   string     `json:"latestCollectionAt"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeAPIError(w, err)
		return
	}
	if !validCoord(req.Origin) {
		writeErr(w, http.StatusBadRequest, "invalid_origin", "invalid origin")
		return
	}
	if req.OriginType == "" {
		req.OriginType = OriginHome
	}
	if req.OriginType != OriginHome && req.OriginType != OriginClinic && req.OriginType != OriginNode {
		writeErr(w, http.StatusBadRequest, "invalid_origin_type", "invalid origin type")
		return
	}
	requestedAt, err := parseTime(req.RequestedAt, "invalid_time")
	if err != nil {
		writeAPIError(w, err)
		return
	}
	deadline, err := parseTime(req.DeliveryDeadline, "invalid_deadline")
	if err != nil {
		writeAPIError(w, err)
		return
	}
	if !deadline.After(requestedAt) {
		writeErr(w, http.StatusBadRequest, "invalid_deadline", "invalid deadline")
		return
	}
	earliest := requestedAt
	if req.EarliestCollectionAt != "" {
		earliest, err = parseTime(req.EarliestCollectionAt, "invalid_collection_window")
		if err != nil {
			writeAPIError(w, err)
			return
		}
	}
	latest := deadline
	if req.LatestCollectionAt != "" {
		latest, err = parseTime(req.LatestCollectionAt, "invalid_collection_window")
		if err != nil {
			writeAPIError(w, err)
			return
		}
	}
	if latest.Before(earliest) {
		writeErr(w, http.StatusBadRequest, "invalid_collection_window", "invalid collection window")
		return
	}
	ctx := r.Context()
	res, err := st.evaluateServiceability(ctx, req.Origin, req.OriginType, req.OriginNodeID, req.SampleTypeID, requestedAt, deadline, earliest, latest)
	if err != nil {
		writeAPIError(w, err)
		return
	}
	out := map[string]any{
		"serviceable":           res.Serviceable,
		"reason":                res.Reason,
		"serviceabilityVersion": res.ServiceabilityVersion,
	}
	if res.TargetLaboratoryID != "" {
		out["targetLaboratoryId"] = res.TargetLaboratoryID
	}
	if !res.EstimatedArrivalAt.IsZero() {
		out["estimatedArrivalAt"] = formatTime(res.EstimatedArrivalAt)
	}
	st.audit(ctx, sess, "check_serviceability", "serviceability", req.SampleTypeID, true, map[string]any{"reason": res.Reason})
	writeData(w, http.StatusOK, out)
}
"}

