	}
	writeData(w, http.StatusOK, payload)
}

func (st *Store) handleReadSampleLifecycle(w http.ResponseWriter, r *http.Request) {
	sess := sessionFrom(r.Context())
	if err := sess.requireActiveRole(); err != nil {
		writeAPIError(w, err)
		return
	}
	sampleID := r.PathValue("sampleId")
	if !st.canSeeSample(r.Context(), sess, sampleID) {
		writeErr(w, http.StatusForbidden, "forbidden", "forbidden")
		return
	}
	var exists int
	_ = st.PG.QueryRowContext(r.Context(), `SELECT COUNT(*) FROM samples WHERE sample_id = $1`, sampleID).Scan(&exists)
	if exists == 0 {
		writeErr(w, http.StatusNotFound, "not_found", "not found")
		return
	}
	tl, _ := st.loadTimelineForSample(r.Context(), sampleID)
	writeData(w, http.StatusOK, map[string]any{
		"sampleId": sampleID,
		"timeline": tl,
	})
}

func (st *Store) canSeeSample(ctx context.Context, sess *Session, sampleID string) bool {
	if isAdminOrDispatcher(sess.ActiveRole) {
		return true
	}
	var requester, holder sql.NullString
	err := st.PG.QueryRowContext(ctx, `SELECT requester_id, current_holder_id FROM samples WHERE sample_id = $1`, sampleID).Scan(&requester, &holder)
	if err != nil {
		return false
	}
	if sess.ActiveRole == RoleRequester && requester.Valid && requester.String == sess.UserID {
		return true
	}
	if holder.Valid && holder.String == sess.UserID {
		return true
	}
	var n int
	_ = st.PG.QueryRowContext(ctx, `
		SELECT COUNT(*) FROM assignments
		WHERE sample_id = $1 AND (worker_id = $2 OR offered_worker_id = $2)`, sampleID, sess.UserID).Scan(&n)
	return n > 0
}

func (st *Store) sampleStatePayload(ctx context.Context, sess *Session, sampleID string) (map[string]any, error) {
	var requestID, requesterID, typeID, status, svc, svcReason string
	var sealed bool
	var holder, target, recvLab sql.NullString
	var sealedAt, recvAt, locAt sql.NullTime
	var lat, lng sql.NullFloat64
	var exc []byte
	err := st.PG.QueryRowContext(ctx, `
		SELECT request_id, requester_id, sample_type_id, status, sealed, sealed_at, current_holder_id,
		       target_laboratory_id, received_laboratory_id, received_at, serviceability, serviceability_reason,
		       latest_lat, latest_lng, location_recorded_at, exception
		FROM samples WHERE sample_id = $1`, sampleID).
		Scan(&requestID, &requesterID, &typeID, &status, &sealed, &sealedAt, &holder, &target, &recvLab, &recvAt,
			&svc, &svcReason, &lat, &lng, &locAt, &exc)
	if err == sql.ErrNoRows {
		return nil, errJSON("not_found", "not found", http.StatusNotFound)
	}
	if err != nil {
		return nil, err
	}
	if !st.canSeeSample(ctx, sess, sampleID) {
		return nil, errJSON("forbidden", "forbidden", http.StatusForbidden)
	}
	var originLat, originLng float64
	var originType string
	var originNode sql.NullString
	var requested, deadline, earliest, latest time.Time
	_ = st.PG.QueryRowContext(ctx, `
		SELECT origin_lat, origin_lng, origin_type, origin_node_id, requested_at, delivery_deadline,
		       earliest_collection_at, latest_collection_at
		FROM collection_requests WHERE request_id = $1`, requestID).
		Scan(&originLat, &originLng, &originType, &originNode, &requested, &deadline, &earliest, &latest)

	now := time.Now().UTC()
	var rec *time.Time
	if locAt.Valid {
		rec = &locAt.Time
	}
	var coord any
	if lat.Valid && lng.Valid {
		coord = Coordinate{Latitude: lat.Float64, Longitude: lng.Float64}
	}
	var excObj any
	if len(exc) > 0 && string(exc) != "null" {
		var m map[string]any
		if json.Unmarshal(exc, &m) == nil {
			excObj = m
		}
	}
	var journeyID sql.NullString
	_ = st.PG.QueryRowContext(ctx, `
		SELECT js.journey_id FROM journey_samples js
		JOIN journeys j ON j.journey_id = js.journey_id
		WHERE js.sample_id = $1 AND j.active = TRUE
		ORDER BY j.plan_version DESC LIMIT 1`, sampleID).Scan(&journeyID)

	return map[string]any{
		"sampleId":             sampleID,
		"requestId":            requestID,
		"status":               status,
		"currentHolderId":      nullStr(holder),
		"latestCoordinate":     coord,
		"locationRecordedAt":   formatTimePtr(rec),
		"locationStale":        isLocationStale(rec, now),
		"sealed":               sealed,
		"serviceability":       svc,
		"serviceabilityReason": svcReason,
		"targetLaboratoryId":   nullStr(target),
		"receivedLaboratoryId": nullStr(recvLab),
		"exception":            excObj,
		"journeyId":            nullStr(journeyID),
		"origin":               Coordinate{Latitude: originLat, Longitude: originLng},
		"originType":           originType,
		"deliveryDeadline":     formatTime(deadline),
	}, nil
}

func formatTimePtr(t *time.Time) any {
	if t == nil || t.IsZero() {
		return nil
	}
	return formatTime(*t)
}
"}

