func (st *Store) expireOffers(ctx context.Context) {
	rows, err := st.PG.QueryContext(ctx, `
		SELECT assignment_id, offered_worker_id, kind, sample_id, journey_id, node_id, laboratory_id
		FROM assignments
		WHERE status = 'offered' AND offer_expires_at IS NOT NULL AND offer_expires_at < now()`)
	if err != nil {
		return
	}
	type exp struct {
		asg, worker, kind, sample, journey string
		node, lab                          sql.NullString
	}
	var list []exp
	for rows.Next() {
		var e exp
		if err := rows.Scan(&e.asg, &e.worker, &e.kind, &e.sample, &e.journey, &e.node, &e.lab); err == nil {
			list = append(list, e)
		}
	}
	rows.Close()
	for _, e := range list {
		_, _ = st.PG.ExecContext(ctx, `
			INSERT INTO assignment_declines (assignment_id, worker_id, reason)
			VALUES ($1,$2,'offer_expired') ON CONFLICT DO NOTHING`, e.asg, e.worker)
		st.reoffer(ctx, e.asg, e.kind, e.sample, e.journey, nullStr(e.node), nullStr(e.lab), e.worker)
	}
}

func (st *Store) reoffer(ctx context.Context, asgID, kind, sampleID, journeyID, nodeID, labID, exclude string) {
	loc := nodeID
	if loc == "" {
		loc = labID
	}
	qual := ""
	if kind == KindCollection {
		_ = st.PG.QueryRowContext(ctx, `
			SELECT st.required_qualification
			FROM samples s JOIN sample_types st ON st.sample_type_id = s.sample_type_id
			WHERE s.sample_id = $1`, sampleID).Scan(&qual)
	}
	_ = st.tx(ctx, func(tx *sql.Tx) error {
		next := st.pickWorkerTx(ctx, tx, kind, loc, qual, exclude)
		if next == "" {
			_, _ = tx.ExecContext(ctx, `
				UPDATE assignments SET status = 'pending', offered_worker_id = NULL, offer_expires_at = NULL
				WHERE assignment_id = $1`, asgID)
			// flag exception if collection/lab assignment has been waiting too long
			var created time.Time
			_ = tx.QueryRowContext(ctx, `SELECT created_at FROM assignments WHERE assignment_id = $1`, asgID).Scan(&created)
			if time.Since(created) > noWorkerWait {
				exc, _ := json.Marshal(map[string]any{
					"reason": "no_qualified_worker",
					"code":   "no_qualified_worker",
				})
				_, _ = tx.ExecContext(ctx, `UPDATE samples SET status = $1, exception = $2 WHERE sample_id = $3 AND status NOT IN ('received','cancelled')`,
					SampleException, exc, sampleID)
			}
			return nil
		}
		_, _ = tx.ExecContext(ctx, `
			UPDATE assignments SET status = 'offered', offered_worker_id = $1, offer_expires_at = $2, worker_id = NULL
			WHERE assignment_id = $3`, next, time.Now().Add(offerTTL), asgID)
		return nil
	})
	st.emitEvent(ctx, "assignment_offered", "assignment", asgID, map[string]any{"sampleId": sampleID}, "")
}

func (st *Store) handleAcceptAssignment(w http.ResponseWriter, r *http.Request) {
	sess := sessionFrom(r.Context())
	if err := sess.requireAny(RoleCollection, RoleDelivery, RoleNode, RoleLab, RoleAdministrator, RoleDispatcher); err != nil {
		writeAPIError(w, err)
		return
	}
	var req struct {
		AssignmentID   string `json:"assignmentId"`
		IdempotencyKey string `json:"idempotencyKey"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeAPIError(w, err)
		return
	}
	ctx := r.Context()
	if req.IdempotencyKey != "" {
		hash := hashRequest("accept", req.AssignmentID, sess.UserID)
		hit, status, body, err := st.checkIdempotency(ctx, sess.UserID, req.IdempotencyKey, "accept", hash)
		if err != nil {
			writeAPIError(w, err)
			return
		}
		if hit {
			replayIdempotent(w, status, body)
			return
		}
	}
	st.expireOffers(ctx)
	var offered sql.NullString
	var status, sampleID, kind string
	err := st.PG.QueryRowContext(ctx, `
		SELECT offered_worker_id, status, sample_id, kind FROM assignments WHERE assignment_id = $1`, req.AssignmentID).
		Scan(&offered, &status, &sampleID, &kind)
	if err == sql.ErrNoRows {
		writeErr(w, http.StatusNotFound, "not_found", "not found")
		return
	}
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", "internal error")
		return
	}
	if status == AssignAccepted || status == AssignInProgress || status == AssignCompleted ||
		status == AssignPickedUp || status == AssignInTransit || status == AssignArrived || status == AssignDelivered {
		// already accepted by this worker?
		var worker sql.NullString
		_ = st.PG.QueryRowContext(ctx, `SELECT worker_id FROM assignments WHERE assignment_id = $1`, req.AssignmentID).Scan(&worker)
		if worker.Valid && worker.String == sess.UserID {
			out := map[string]any{"assignmentId": req.AssignmentID, "status": status}
			writeData(w, http.StatusOK, out)
			return
		}
	}
	if status != AssignOffered && status != AssignPending {
		writeErr(w, http.StatusConflict, "assignment_not_offered", "assignment not offered")
		return
	}
	if !offered.Valid || offered.String != sess.UserID {
		if !isAdminOrDispatcher(sess.ActiveRole) {
			writeErr(w, http.StatusForbidden, "assignment_not_offered", "assignment not offered to this worker")
			return
		}
	}
	_, err = st.PG.ExecContext(ctx, `
		UPDATE assignments SET status = 'accepted', worker_id = $1, offered_worker_id = $1
		WHERE assignment_id = $2`, sess.UserID, req.AssignmentID)
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", "internal error")
		return
	}
	if kind == KindCollection {
		_, _ = st.PG.ExecContext(ctx, `UPDATE samples SET status = $1 WHERE sample_id = $2 AND status IN ('requested','assigned')`,
			SampleAssigned, sampleID)
	}
	st.audit(ctx, sess, "accept_assignment", "assignment", req.AssignmentID, true, map[string]any{"sampleId": sampleID})
	_, _ = st.writeTimeline(ctx, nil, sampleID, "", req.AssignmentID, "accept_assignment", sess.UserID, sess.ActiveRole, "assignment", req.AssignmentID, true, nil)
	st.emitEvent(ctx, "assignment_accepted", "assignment", req.AssignmentID, map[string]any{"sampleId": sampleID}, "")
	out := map[string]any{"assignmentId": req.AssignmentID, "status": AssignAccepted}
	if req.IdempotencyKey != "" {
		st.saveIdempotency(ctx, sess.UserID, req.IdempotencyKey, "accept", hashRequest("accept", req.AssignmentID, sess.UserID), http.StatusOK, out)
	}
	writeData(w, http.StatusOK, out)
}

