	}
	allowed := map[string]bool{
		AssignAccepted: true, AssignInProgress: true, AssignAtPickup: true, AssignPickedUp: true,
		AssignInTransit: true, AssignArrived: true, AssignDelivered: true, AssignCompleted: true,
