		writeAPIError(w, err)
		return
	}
	ctx := r.Context()
	if req.IdempotencyKey != "" {
		hash := hashRequest("progress", req.AssignmentID, req.Status, req.OccurredAt)
		hit, status, body, err := st.checkIdempotency(ctx, sess.UserID, req.IdempotencyKey, "progress", hash)
		if err != nil {
			writeAPIError(w, err)
			return
		}
		if hit {
			replayIdempotent(w, status, body)
			return
		}
