	var worker sql.NullString
	var cur, sampleID, kind string
	err = st.PG.QueryRowContext(ctx, `
		SELECT worker_id, status, sample_id, kind FROM assignments WHERE assignment_id = $1`, req.AssignmentID).
		Scan(&worker, &cur, &sampleID, &kind)
	if err == sql.ErrNoRows {
		writeErr(w, http.StatusNotFound, "not_found", "not found")
		return
	}
	if !worker.Valid || worker.String != sess.UserID {
		if !isAdminOrDispatcher(sess.ActiveRole) {
			writeErr(w, http.StatusForbidden, "forbidden", "forbidden")
			return
		}
	}
	if cur == AssignCompleted || cur == AssignCancelled || cur == AssignDelivered {
		if cur == req.Status {
			writeData(w, http.StatusOK, map[string]any{"assignmentId": req.AssignmentID, "status": cur})
			return
		}
		writeErr(w, http.StatusConflict, "assignment_completed", "assignment already completed")
		return
	}
	_, err = st.PG.ExecContext(ctx, `UPDATE assignments SET status = $1 WHERE assignment_id = $2`, req.Status, req.AssignmentID)
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", "internal error")
		return
	}
	if req.Status == AssignInProgress || req.Status == AssignPickedUp || req.Status == AssignInTransit {
		if kind == KindTransport {
			_, _ = st.PG.ExecContext(ctx, `UPDATE samples SET status = $1 WHERE sample_id = $2 AND status NOT IN ('received','cancelled','exception')`,
				SampleInTransit, sampleID)
		}
		if kind == KindCollection {
			_, _ = st.PG.ExecContext(ctx, `UPDATE samples SET status = $1 WHERE sample_id = $2 AND status IN ('requested','assigned')`,
				SampleCollecting, sampleID)
		}
	}
	if req.Status == AssignCompleted || req.Status == AssignDelivered {
		_, _ = st.PG.ExecContext(ctx, `UPDATE assignments SET completed_at = $1 WHERE assignment_id = $2`, occurred, req.AssignmentID)
	}
	st.audit(ctx, sess, "update_assignment_progress", "assignment", req.AssignmentID, true, map[string]any{"status": req.Status, "sampleId": sampleID})
	_, _ = st.writeTimeline(ctx, nil, sampleID, "", req.AssignmentID, "update_assignment_progress", sess.UserID, sess.ActiveRole, "assignment", req.AssignmentID, true, map[string]any{"status": req.Status})
	out := map[string]any{"assignmentId": req.AssignmentID, "status": req.Status}
	if req.IdempotencyKey != "" {
		st.saveIdempotency(ctx, sess.UserID, req.IdempotencyKey, "progress", hashRequest("progress", req.AssignmentID, req.Status, req.OccurredAt), http.StatusOK, out)
	}
	writeData(w, http.StatusOK, out)
}

func (st *Store) handleCollectAndSeal(w http.ResponseWriter, r *http.Request) {
	sess := sessionFrom(r.Context())
	if err := sess.requireAny(RoleCollection, RoleAdministrator, RoleDispatcher); err != nil {
		writeAPIError(w, err)
		return
	}
	var req struct {
		SampleID              string  `json:"sampleId"`
		AssignmentID          string  `json:"assignmentId"`
		CollectedAt           string  `json:"collectedAt"`
		ContainerType         string  `json:"containerType"`
		ObservedTemperatureC  float64 `json:"observedTemperatureC"`
		IdempotencyKey        string  `json:"idempotencyKey"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeAPIError(w, err)
		return
	}
	ctx := r.Context()
	if req.IdempotencyKey != "" {
		hash := hashRequest("seal", req.SampleID, req.AssignmentID)
		hit, status, body, err := st.checkIdempotency(ctx, sess.UserID, req.IdempotencyKey, "seal", hash)
		if err != nil {
			writeAPIError(w, err)
			return
		}
		if hit {
			replayIdempotent(w, status, body)
			return
		}
	}
	collectedAt, err := parseTime(req.CollectedAt, "invalid_time")
	if err != nil {
		writeAPIError(w, err)
		return
	}
	var earliest, latest time.Time
	var originType string
	err = st.PG.QueryRowContext(ctx, `
		SELECT r.earliest_collection_at, r.latest_collection_at, r.origin_type
		FROM samples s JOIN collection_requests r ON r.request_id = s.request_id
		WHERE s.sample_id = $1`, req.SampleID).Scan(&earliest, &latest, &originType)
	if err == sql.ErrNoRows {
		writeErr(w, http.StatusNotFound, "not_found", "not found")
		return
	}
	if collectedAt.Before(earliest) || collectedAt.After(latest) {
		writeErr(w, http.StatusConflict, "outside_collection_window", "outside collection window")
		return
	}
	var worker sql.NullString
	var kind, astatus, asample string
	err = st.PG.QueryRowContext(ctx, `
		SELECT worker_id, kind, status, sample_id FROM assignments WHERE assignment_id = $1`, req.AssignmentID).
		Scan(&worker, &kind, &astatus, &asample)
	if err == sql.ErrNoRows || asample != req.SampleID {
		writeErr(w, http.StatusNotFound, "not_found", "not found")
		return
	}
	if kind != KindCollection {
		writeErr(w, http.StatusConflict, "invalid_assignment", "not a collection assignment")
		return
	}
	if !worker.Valid || worker.String != sess.UserID {
		if !isAdminOrDispatcher(sess.ActiveRole) {
			writeErr(w, http.StatusForbidden, "forbidden", "forbidden")
			return
		}
	}
	var sealed bool
	var minT, maxT float64
	var reqContainer string
	_ = st.PG.QueryRowContext(ctx, `
		SELECT s.sealed, r.temperature_min_c, r.temperature_max_c, r.container_type
		FROM samples s JOIN collection_requests r ON r.request_id = s.request_id
		WHERE s.sample_id = $1`, req.SampleID).Scan(&sealed, &minT, &maxT, &reqContainer)
	if sealed {
		out := map[string]any{"sampleId": req.SampleID, "status": SampleSealed, "sealed": true}
		writeData(w, http.StatusOK, out)
		return
	}
	compliant := req.ObservedTemperatureC >= minT && req.ObservedTemperatureC <= maxT
	if req.ContainerType != "" && reqContainer != "" && req.ContainerType != reqContainer {
		compliant = false
	}
	status := SampleSealed
	var exc any
	if !compliant {
		status = SampleException
		excMap := map[string]any{
			"reason":                "handling_checkpoint_failed",
			"containerType":         req.ContainerType,
			"observedTemperatureC":  req.ObservedTemperatureC,
		}
		b, _ := json.Marshal(excMap)
		exc = b
	}
	_, err = st.PG.ExecContext(ctx, `
		UPDATE samples SET status = $1, sealed = TRUE, sealed_at = $2, current_holder_id = $3, exception = COALESCE($4, exception)
		WHERE sample_id = $5`, status, collectedAt, sess.UserID, exc, req.SampleID)
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", "internal error")
		return
	}
	_, _ = st.PG.ExecContext(ctx, `
		UPDATE assignments SET status = 'completed', completed_at = $1 WHERE assignment_id = $2`, collectedAt, req.AssignmentID)
	_, _ = st.PG.ExecContext(ctx, `
		INSERT INTO handling_checkpoints (sample_id, assignment_id, container_type, observed_temperature_c, recorded_at, compliant)
		VALUES ($1,$2,$3,$4,$5,$6)`, req.SampleID, req.AssignmentID, req.ContainerType, req.ObservedTemperatureC, collectedAt, compliant)
	st.audit(ctx, sess, "collect_and_seal_sample", "sample", req.SampleID, true, map[string]any{"assignmentId": req.AssignmentID})
	_, _ = st.writeTimeline(ctx, nil, req.SampleID, "", req.AssignmentID, "collect_and_seal_sample", sess.UserID, sess.ActiveRole, "sample", req.SampleID, true, map[string]any{"sealed": true})
	st.emitEvent(ctx, "sample_sealed", "sample", req.SampleID, map[string]any{"status": status}, "")
	out := map[string]any{"sampleId": req.SampleID, "status": status, "sealed": true}
	if req.IdempotencyKey != "" {
		st.saveIdempotency(ctx, sess.UserID, req.IdempotencyKey, "seal", hashRequest("seal", req.SampleID, req.AssignmentID), http.StatusOK, out)
	}
	writeData(w, http.StatusOK, out)
}

func (st *Store) handleInitiateHandoff(w http.ResponseWriter, r *http.Request) {
	sess := sessionFrom(r.Context())
	if err := sess.requireAny(RoleCollection, RoleDelivery, RoleNode, RoleLab, RoleAdministrator, RoleDispatcher); err != nil {
		writeAPIError(w, err)
		return
	}
	var req struct {
		SampleID         string `json:"sampleId"`
		FromAssignmentID string `json:"fromAssignmentId"`
		ToAssignmentID   string `json:"toAssignmentId"`
		ReceiverID       string `json:"receiverId"`
		InitiatedAt      string `json:"initiatedAt"`
		IdempotencyKey   string `json:"idempotencyKey"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeAPIError(w, err)
		return
	}
	ctx := r.Context()
	if req.IdempotencyKey != "" {
		hash := hashRequest("handoff", req.SampleID, req.FromAssignmentID, req.ToAssignmentID)
		hit, status, body, err := st.checkIdempotency(ctx, sess.UserID, req.IdempotencyKey, "handoff", hash)
		if err != nil {
			writeAPIError(w, err)
			return
		}
		if hit {
			replayIdempotent(w, status, body)
			return
		}
	}
	initiatedAt, err := parseTime(req.InitiatedAt, "invalid_time")
	if err != nil {
		writeAPIError(w, err)
		return
	}
	var sealed bool
	var holder sql.NullString
	err = st.PG.QueryRowContext(ctx, `SELECT sealed, current_holder_id FROM samples WHERE sample_id = $1`, req.SampleID).
		Scan(&sealed, &holder)
	if err == sql.ErrNoRows {
		writeErr(w, http.StatusNotFound, "not_found", "not found")
		return
	}
	if !sealed {
		writeErr(w, http.StatusConflict, "sample_not_sealed", "sample not sealed")
		return
	}
	if !holder.Valid || holder.String != sess.UserID {
		if !isAdminOrDispatcher(sess.ActiveRole) {
			writeErr(w, http.StatusForbidden, "not_current_holder", "not current holder")
			return
		}
	}
	// existing pending handoff for same pair?
	var existing string
	err = st.PG.QueryRowContext(ctx, `
		SELECT handoff_id FROM handoffs
		WHERE sample_id = $1 AND from_assignment_id = $2 AND to_assignment_id = $3
		  AND status IN ('pending','confirmed')
		ORDER BY created_at DESC LIMIT 1`, req.SampleID, req.FromAssignmentID, req.ToAssignmentID).Scan(&existing)
	if err == nil && existing != "" {
		out := map[string]any{"handoffId": existing, "status": "pending"}
		writeData(w, http.StatusOK, out)
		return
	}
	id := newUUID()
	_, err = st.PG.ExecContext(ctx, `
		INSERT INTO handoffs (handoff_id, sample_id, from_assignment_id, to_assignment_id, sender_id, receiver_id, status, initiated_at)
		VALUES ($1,$2,$3,$4,$5,$6,'pending',$7)`,
		id, req.SampleID, req.FromAssignmentID, req.ToAssignmentID, sess.UserID, req.ReceiverID, initiatedAt)
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", "internal error")
		return
	}
	st.audit(ctx, sess, "initiate_handoff", "handoff", id, true, map[string]any{"sampleId": req.SampleID})
	_, _ = st.writeTimeline(ctx, nil, req.SampleID, "", req.FromAssignmentID, "initiate_handoff", sess.UserID, sess.ActiveRole, "handoff", id, true, map[string]any{"receiverId": req.ReceiverID})
	st.emitEvent(ctx, "handoff_initiated", "handoff", id, map[string]any{"sampleId": req.SampleID}, "")
	out := map[string]any{"handoffId": id, "status": "pending"}
	if req.IdempotencyKey != "" {
		st.saveIdempotency(ctx, sess.UserID, req.IdempotencyKey, "handoff", hashRequest("handoff", req.SampleID, req.FromAssignmentID, req.ToAssignmentID), http.StatusCreated, out)
	}
	writeData(w, http.StatusCreated, out)
}

func (st *Store) handleConfirmHandoff(w http.ResponseWriter, r *http.Request) {
	sess := sessionFrom(r.Context())
	if err := sess.requireAny(RoleCollection, RoleDelivery, RoleNode, RoleLab, RoleAdministrator, RoleDispatcher); err != nil {
		writeAPIError(w, err)
		return
	}
	var req struct {
		HandoffID        string `json:"handoffId"`
		ConfirmationSide string `json:"confirmationSide"`
		ConfirmedAt      string `json:"confirmedAt"`
		IdempotencyKey   string `json:"idempotencyKey"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeAPIError(w, err)
		return
	}
	if req.ConfirmationSide != "sender" && req.ConfirmationSide != "receiver" {
		writeErr(w, http.StatusBadRequest, "invalid_confirmation_side", "invalid confirmation side")
		return
	}
	confirmedAt, err := parseTime(req.ConfirmedAt, "invalid_time")
	if err != nil {
		writeAPIError(w, err)
		return
	}
	ctx := r.Context()
	if req.IdempotencyKey != "" {
		hash := hashRequest("confirm_handoff", req.HandoffID, req.ConfirmationSide)
		hit, status, body, err := st.checkIdempotency(ctx, sess.UserID, req.IdempotencyKey, "confirm_handoff", hash)
		if err != nil {
			writeAPIError(w, err)
			return
		}
		if hit {
			replayIdempotent(w, status, body)
			return
		}
	}
	var sampleID, senderID, receiverID, status string
	var sConf, rConf bool
	err = st.PG.QueryRowContext(ctx, `
		SELECT sample_id, sender_id, receiver_id, status, sender_confirmed, receiver_confirmed
		FROM handoffs WHERE handoff_id = $1`, req.HandoffID).
		Scan(&sampleID, &senderID, &receiverID, &status, &sConf, &rConf)
	if err == sql.ErrNoRows {
		writeErr(w, http.StatusNotFound, "not_found", "not found")
		return
	}
	if req.ConfirmationSide == "sender" {
		if sess.UserID != senderID && !isAdminOrDispatcher(sess.ActiveRole) {
			writeErr(w, http.StatusForbidden, "forbidden", "forbidden")
			return
		}
		sConf = true
		_, _ = st.PG.ExecContext(ctx, `UPDATE handoffs SET sender_confirmed = TRUE WHERE handoff_id = $1`, req.HandoffID)
	} else {
		if sess.UserID != receiverID && !isAdminOrDispatcher(sess.ActiveRole) {
			writeErr(w, http.StatusForbidden, "forbidden", "forbidden")
			return
		}
		rConf = true
		_, _ = st.PG.ExecContext(ctx, `UPDATE handoffs SET receiver_confirmed = TRUE WHERE handoff_id = $1`, req.HandoffID)
	}
	final := "pending"
	if sConf && rConf {
		final = "confirmed"
		if status != "confirmed" {
			_, _ = st.PG.ExecContext(ctx, `
				UPDATE handoffs SET status = 'confirmed', confirmed_at = $1 WHERE handoff_id = $2`, confirmedAt, req.HandoffID)
			_, _ = st.PG.ExecContext(ctx, `UPDATE samples SET current_holder_id = $1 WHERE sample_id = $2`, receiverID, sampleID)
		}
	}
	st.audit(ctx, sess, "confirm_handoff", "handoff", req.HandoffID, true, map[string]any{"side": req.ConfirmationSide, "sampleId": sampleID})
	_, _ = st.writeTimeline(ctx, nil, sampleID, "", "", "confirm_handoff", sess.UserID, sess.ActiveRole, "handoff", req.HandoffID, true, map[string]any{"side": req.ConfirmationSide, "status": final})
	if final == "confirmed" {
		st.emitEvent(ctx, "handoff_confirmed", "handoff", req.HandoffID, map[string]any{"sampleId": sampleID, "holderId": receiverID}, "")
	}
	out := map[string]any{"handoffId": req.HandoffID, "status": final}
	if req.IdempotencyKey != "" {
		st.saveIdempotency(ctx, sess.UserID, req.IdempotencyKey, "confirm_handoff", hashRequest("confirm_handoff", req.HandoffID, req.ConfirmationSide), http.StatusOK, out)
	}
	writeData(w, http.StatusOK, out)
}

