func (st *Store) handleConfirmLabReceipt(w http.ResponseWriter, r *http.Request) {
	sess := sessionFrom(r.Context())
	if err := sess.requireAny(RoleLab, RoleAdministrator, RoleDispatcher); err != nil {
		writeAPIError(w, err)
		return
	}
	var req struct {
		SampleID       string `json:"sampleId"`
		LaboratoryID   string `json:"laboratoryId"`
		ReceivedAt     string `json:"receivedAt"`
		IdempotencyKey string `json:"idempotencyKey"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeAPIError(w, err)
		return
	}
	receivedAt, err := parseTime(req.ReceivedAt, "invalid_time")
	if err != nil {
		writeAPIError(w, err)
		return
	}
	ctx := r.Context()
	if req.IdempotencyKey != "" {
		hash := hashRequest("lab_receipt", req.SampleID, req.LaboratoryID)
		hit, status, body, err := st.checkIdempotency(ctx, sess.UserID, req.IdempotencyKey, "lab_receipt", hash)
		if err != nil {
			writeAPIError(w, err)
			return
		}
		if hit {
			replayIdempotent(w, status, body)
			return
		}
	}
	var status string
	var deadline time.Time
	err = st.PG.QueryRowContext(ctx, `
		SELECT s.status, r.delivery_deadline
		FROM samples s JOIN collection_requests r ON r.request_id = s.request_id
		WHERE s.sample_id = $1`, req.SampleID).Scan(&status, &deadline)
	if err == sql.ErrNoRows {
		writeErr(w, http.StatusNotFound, "not_found", "not found")
		return
	}
	if status == SampleReceived {
		out := map[string]any{"sampleId": req.SampleID, "status": SampleReceived}
		writeData(w, http.StatusOK, out)
		return
	}
	final := SampleReceived
	var exc any
	if receivedAt.After(deadline) {
		final = SampleExpired
		b, _ := json.Marshal(map[string]any{"reason": "missed_delivery_deadline"})
		exc = b
	}
	_, err = st.PG.ExecContext(ctx, `
		UPDATE samples SET status = $1, received_laboratory_id = $2, received_at = $3, current_holder_id = $4, exception = COALESCE($5, exception)
		WHERE sample_id = $6`, final, req.LaboratoryID, receivedAt, sess.UserID, exc, req.SampleID)
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", "internal error")
		return
	}
	_, _ = st.PG.ExecContext(ctx, `
		UPDATE assignments SET status = 'completed', completed_at = $1
		WHERE sample_id = $2 AND kind = 'laboratory' AND status NOT IN ('cancelled','completed')`, receivedAt, req.SampleID)
	_, _ = st.PG.ExecContext(ctx, `
		UPDATE journeys SET status = 'completed'
		WHERE journey_id IN (SELECT journey_id FROM journey_samples WHERE sample_id = $1) AND active = TRUE`, req.SampleID)
	st.audit(ctx, sess, "confirm_laboratory_receipt", "sample", req.SampleID, true, map[string]any{"laboratoryId": req.LaboratoryID})
	_, _ = st.writeTimeline(ctx, nil, req.SampleID, "", "", "confirm_laboratory_receipt", sess.UserID, sess.ActiveRole, "sample", req.SampleID, true, map[string]any{"status": final})
	st.emitEvent(ctx, "sample_received", "sample", req.SampleID, map[string]any{"status": final}, "")
	out := map[string]any{"sampleId": req.SampleID, "status": final}
	if req.IdempotencyKey != "" {
		st.saveIdempotency(ctx, sess.UserID, req.IdempotencyKey, "lab_receipt", hashRequest("lab_receipt", req.SampleID, req.LaboratoryID), http.StatusOK, out)
	}
	writeData(w, http.StatusOK, out)
}

