func (st *Store) journeyPlanPayload(ctx context.Context, sess *Session, journeyID string) (map[string]any, error) {
	var parent sql.NullString
	var version int
	var mode, status string
	var eta sql.NullTime
	var cost float64
	var capUsed, capAvail int
	var valid bool
	var replan sql.NullString
	err := st.PG.QueryRowContext(ctx, `
		SELECT parent_journey_id, plan_version, route_mode, status, estimated_delivery_at,
		       total_cost_units, capacity_used, capacity_available, valid, replan_status
		FROM journeys WHERE journey_id = $1`, journeyID).
		Scan(&parent, &version, &mode, &status, &eta, &cost, &capUsed, &capAvail, &valid, &replan)
	if err == sql.ErrNoRows {
		return nil, errJSON("not_found", "not found", http.StatusNotFound)
	}
	if err != nil {
		return nil, err
	}

	sampleIDs, _ := st.journeySampleIDs(ctx, journeyID)
	if sess.ActiveRole == RoleRequester {
		ok := false
		for _, sid := range sampleIDs {
			if st.canSeeSample(ctx, sess, sid) {
				ok = true
				break
			}
		}
		if !ok {
			return nil, errJSON("forbidden", "forbidden", http.StatusForbidden)
		}
	}

	stops := []map[string]any{}
	srows, err := st.PG.QueryContext(ctx, `
		SELECT stop_id, location_id, stop_type, sequence, estimated_at, dwell_minutes
		FROM journey_stops WHERE journey_id = $1 ORDER BY sequence`, journeyID)
	if err == nil {
		defer srows.Close()
		for srows.Next() {
			var sid, lid, stype string
			var seq, dwell int
			var est time.Time
			if err := srows.Scan(&sid, &lid, &stype, &seq, &est, &dwell); err == nil {
				stops = append(stops, map[string]any{
					"stopId":        sid,
					"locationId":    lid,
					"stopType":      stype,
					"sequence":      seq,
					"estimatedAt":   formatTime(est),
					"dwellMinutes":  dwell,
				})
			}
		}
	}

	assignments := []map[string]any{}
	arows, err := st.PG.QueryContext(ctx, `
		SELECT assignment_id, kind, status, from_location_id, to_location_id, worker_id, offered_worker_id, sequence
		FROM assignments WHERE journey_id = $1 ORDER BY sequence`, journeyID)
	if err == nil {
		defer arows.Close()
		for arows.Next() {
			var aid, kind, astatus string
			var from, to, worker, offered sql.NullString
			var seq int
			if err := arows.Scan(&aid, &kind, &astatus, &from, &to, &worker, &offered, &seq); err == nil {
				item := map[string]any{
					"assignmentId": aid,
					"kind":         kind,
					"status":       astatus,
					"sequence":     seq,
				}
				if from.Valid {
					item["fromLocationId"] = from.String
				}
				if to.Valid {
					item["toLocationId"] = to.String
				}
				if worker.Valid {
					item["workerId"] = worker.String
				} else if offered.Valid {
					item["workerId"] = offered.String
				}
				assignments = append(assignments, item)
			}
		}
	}

	// hide extra assignment details for delivery partners
	if sess.ActiveRole == RoleDelivery {
		filtered := []map[string]any{}
		for _, a := range assignments {
			wid, _ := a["workerId"].(string)
			if wid == sess.UserID {
				filtered = append(filtered, a)
			}
		}
		assignments = filtered
	}

	var etaVal any
	if eta.Valid {
		etaVal = formatTime(eta.Time)
	}
	out := map[string]any{
		"journeyId":           journeyID,
		"planVersion":         version,
		"routeMode":           mode,
		"status":              status,
		"estimatedDeliveryAt": etaVal,
		"totalCostUnits":      cost,
		"capacityUsed":        capUsed,
		"capacityAvailable":   capAvail,
		"valid":               valid,
		"stops":               stops,
		"assignments":         assignments,
		"sampleIds":           sampleIDs,
	}
	if parent.Valid {
		out["parentJourneyId"] = parent.String
	}
	if replan.Valid && replan.String != "" {
		out["replanStatus"] = replan.String
	}
	return out, nil
}

func (st *Store) journeySampleIDs(ctx context.Context, journeyID string) ([]string, error) {
	rows, err := st.PG.QueryContext(ctx, `SELECT sample_id FROM journey_samples WHERE journey_id = $1`, journeyID)
	if err != nil {
		return []string{}, err
	}
	return scanStrings(rows)
}

func (st *Store) expectPlanVersion(ctx context.Context, journeyID string, expected int) (int, error) {
	var current int
	err := st.PG.QueryRowContext(ctx, `SELECT plan_version FROM journeys WHERE journey_id = $1`, journeyID).Scan(&current)
	if err == sql.ErrNoRows {
		return 0, errJSON("not_found", "not found", http.StatusNotFound)
	}
	if err != nil {
		return 0, err
	}
	if current != expected {
		return current, errJSON("plan_version_conflict", "plan version conflict", http.StatusConflict)
	}
	return current, nil
}

func (st *Store) bumpPlan(ctx context.Context, tx *sql.Tx, journeyID string) (int, error) {
	var v int
	err := tx.QueryRowContext(ctx, `
		UPDATE journeys SET plan_version = plan_version + 1 WHERE journey_id = $1 RETURNING plan_version`, journeyID).Scan(&v)
	return v, err
}

func (st *Store) handleEditActivePlan(w http.ResponseWriter, r *http.Request) {
	sess := sessionFrom(r.Context())
	if err := sess.requireAny(RoleAdministrator, RoleDispatcher); err != nil {
		writeAPIError(w, err)
		return
	}
	var req struct {
		JourneyID            string         `json:"journeyId"`
		ExpectedPlanVersion  int            `json:"expectedPlanVersion"`
		ChangeType           string         `json:"changeType"`
		Changes              map[string]any `json:"changes"`
		IdempotencyKey       string         `json:"idempotencyKey"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeAPIError(w, err)
		return
	}
	allowed := map[string]bool{"reroute": true, "reassign": true, "reschedule": true, "split": true, "merge": true, "cancel": true}
	if !allowed[req.ChangeType] {
		writeErr(w, http.StatusBadRequest, "invalid_change_type", "invalid change type")
		return
	}
	ctx := r.Context()
	if req.IdempotencyKey != "" {
		hash := hashRequest("edit", req.JourneyID, req.ChangeType, itoa(req.ExpectedPlanVersion))
		hit, status, body, err := st.checkIdempotency(ctx, sess.UserID, req.IdempotencyKey, "edit", hash)
		if err != nil {
			writeAPIError(w, err)
			return
		}
		if hit {
			replayIdempotent(w, status, body)
			return
		}
	}
	if _, err := st.expectPlanVersion(ctx, req.JourneyID, req.ExpectedPlanVersion); err != nil {
		writeAPIError(w, err)
		return
	}
	var newVersion int
	err := st.tx(ctx, func(tx *sql.Tx) error {
		v, err := st.bumpPlan(ctx, tx, req.JourneyID)
		if err != nil {
			return err
		}
		newVersion = v
		// apply limited changes without rewriting completed work
		if req.ChangeType == "cancel" {
			_, _ = tx.ExecContext(ctx, `
				UPDATE assignments SET status = 'cancelled'
				WHERE journey_id = $1 AND status NOT IN ('completed','delivered','cancelled')`, req.JourneyID)
			_, _ = tx.ExecContext(ctx, `UPDATE journeys SET status = 'cancelled' WHERE journey_id = $1`, req.JourneyID)
			st.releaseJourneyCapacity(ctx, tx, req.JourneyID)
		}
		if req.ChangeType == "reassign" {
			if asg, ok := req.Changes["assignmentId"].(string); ok {
				if worker, ok := req.Changes["workerId"].(string); ok {
					var status string
					_ = tx.QueryRowContext(ctx, `SELECT status FROM assignments WHERE assignment_id = $1`, asg).Scan(&status)
					if status == AssignCompleted || status == AssignDelivered || status == AssignCancelled {
						return errJSON("completed_work_immutable", "completed work cannot be rewritten", http.StatusConflict)
					}
					_, _ = tx.ExecContext(ctx, `
						UPDATE assignments SET worker_id = $1, offered_worker_id = $1, status = 'offered',
						  offer_expires_at = $2 WHERE assignment_id = $3`, worker, time.Now().Add(offerTTL), asg)
				}
			}
		}
		return nil
	})
	if err != nil {
		writeAPIError(w, err)
		return
	}
	st.audit(ctx, sess, "edit_active_plan", "journey", req.JourneyID, true, map[string]any{"changeType": req.ChangeType, "planVersion": newVersion})
	_, _ = st.writeTimeline(ctx, nil, "", req.JourneyID, "", "edit_active_plan", sess.UserID, sess.ActiveRole, "journey", req.JourneyID, true, map[string]any{"changeType": req.ChangeType})
	out := map[string]any{"journeyId": req.JourneyID, "planVersion": newVersion, "status": "updated"}
	if req.IdempotencyKey != "" {
		st.saveIdempotency(ctx, sess.UserID, req.IdempotencyKey, "edit", hashRequest("edit", req.JourneyID, req.ChangeType, itoa(req.ExpectedPlanVersion)), http.StatusOK, out)
	}
	writeData(w, http.StatusOK, out)
}

