func (st *Store) handleMergeJourneys(w http.ResponseWriter, r *http.Request) {
	sess := sessionFrom(r.Context())
	if err := sess.requireAny(RoleAdministrator, RoleDispatcher); err != nil {
		writeAPIError(w, err)
		return
	}
	var req struct {
		TargetJourneyID     string   `json:"targetJourneyId"`
		ExpectedPlanVersion int      `json:"expectedPlanVersion"`
		SourceJourneyIDs    []string `json:"sourceJourneyIds"`
		IdempotencyKey      string   `json:"idempotencyKey"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeAPIError(w, err)
		return
	}
	if len(req.SourceJourneyIDs) == 0 {
		writeErr(w, http.StatusBadRequest, "invalid_merge", "invalid merge")
		return
	}
	ctx := r.Context()
	if req.IdempotencyKey != "" {
		hash := hashRequest("merge", req.TargetJourneyID, itoa(req.ExpectedPlanVersion))
		hit, status, body, err := st.checkIdempotency(ctx, sess.UserID, req.IdempotencyKey, "merge", hash)
		if err != nil {
			writeAPIError(w, err)
			return
		}
		if hit {
			replayIdempotent(w, status, body)
			return
		}
	}
	if _, err := st.expectPlanVersion(ctx, req.TargetJourneyID, req.ExpectedPlanVersion); err != nil {
		writeAPIError(w, err)
		return
	}
	// validate compatibility of samples
	if err := st.validateMerge(ctx, req.TargetJourneyID, req.SourceJourneyIDs); err != nil {
		writeAPIError(w, err)
		return
	}
	var newVersion int
	err := st.tx(ctx, func(tx *sql.Tx) error {
		v, err := st.bumpPlan(ctx, tx, req.TargetJourneyID)
		if err != nil {
			return err
		}
		newVersion = v
		for _, src := range req.SourceJourneyIDs {
			sids, _ := st.journeySampleIDs(ctx, src)
			for _, sid := range sids {
				_, _ = tx.ExecContext(ctx, `INSERT INTO journey_samples (journey_id, sample_id) VALUES ($1,$2) ON CONFLICT DO NOTHING`, req.TargetJourneyID, sid)
				_, _ = tx.ExecContext(ctx, `
					UPDATE assignments SET journey_id = $1
					WHERE journey_id = $2 AND sample_id = $3 AND status NOT IN ('completed','delivered','cancelled')`,
					req.TargetJourneyID, src, sid)
			}
			_, _ = tx.ExecContext(ctx, `UPDATE journeys SET active = FALSE, status = 'replaced' WHERE journey_id = $1`, src)
		}
		_, _ = tx.ExecContext(ctx, `UPDATE journeys SET route_mode = 'batched' WHERE journey_id = $1`, req.TargetJourneyID)
		return nil
	})
	if err != nil {
		writeAPIError(w, err)
		return
	}
	st.audit(ctx, sess, "merge_journeys", "journey", req.TargetJourneyID, true, map[string]any{"sources": req.SourceJourneyIDs})
	out := map[string]any{"journeyId": req.TargetJourneyID, "planVersion": newVersion}
	if req.IdempotencyKey != "" {
		st.saveIdempotency(ctx, sess.UserID, req.IdempotencyKey, "merge", hashRequest("merge", req.TargetJourneyID, itoa(req.ExpectedPlanVersion)), http.StatusOK, out)
	}
	writeData(w, http.StatusOK, out)
}

func (st *Store) validateMerge(ctx context.Context, target string, sources []string) error {
	type meta struct {
		typeID, container string
		cooled, batch     bool
		incompat          []string
	}
	load := func(jid string) []meta {
		rows, err := st.PG.QueryContext(ctx, `
			SELECT s.sample_type_id, st.container_type, st.requires_cooled_route, st.batching_allowed
			FROM journey_samples js
			JOIN samples s ON s.sample_id = js.sample_id
			JOIN sample_types st ON st.sample_type_id = s.sample_type_id
			WHERE js.journey_id = $1`, jid)
		if err != nil {
			return nil
		}
		defer rows.Close()
		var out []meta
		for rows.Next() {
			var m meta
			if err := rows.Scan(&m.typeID, &m.container, &m.cooled, &m.batch); err == nil {
				m.incompat, _ = st.loadIncompat(ctx, m.typeID)
				out = append(out, m)
			}
		}
		return out
	}
	all := load(target)
	for _, s := range sources {
		all = append(all, load(s)...)
	}
	for i := 0; i < len(all); i++ {
		if !all[i].batch {
			return errJSON("incompatible_batch", "incompatible batch", http.StatusConflict)
		}
		for j := i + 1; j < len(all); j++ {
			if all[i].container != all[j].container {
				return errJSON("incompatible_container", "incompatible container", http.StatusConflict)
			}
			if all[i].cooled != all[j].cooled {
				return errJSON("incompatible_temperature", "incompatible temperature", http.StatusConflict)
			}
			if containsStr(all[i].incompat, all[j].typeID) || containsStr(all[j].incompat, all[i].typeID) {
				return errJSON("incompatible_sample_types", "incompatible sample types", http.StatusConflict)
			}
		}
	}
	return nil
}

