			return
		}
		if body.Role != "" {
			if !sess.hasRole(body.Role) && !isAdminOrDispatcher(sess.ActiveRole) {
				writeErr(w, http.StatusForbidden, "forbidden", "forbidden")
				return
			}
			if !validRole(body.Role) {
				writeErr(w, http.StatusBadRequest, "invalid_role", "invalid role")
				return
			}
			role = body.Role
		}
		statusFilter = body.Status
	}
	if q := r.URL.Query().Get("role"); q != "" {
		role = q
	}
	if q := r.URL.Query().Get("status"); q != "" {
		statusFilter = q
	}
	st.expireOffers(r.Context())
	items, err := st.listWork(r.Context(), sess, role, statusFilter)
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", "internal error")
		return
	}
	writeData(w, http.StatusOK, map[string]any{
		"role":  role,
		"items": items,
	})
}

func (st *Store) listWork(ctx context.Context, sess *Session, role, statusFilter string) ([]map[string]any, error) {
	now := time.Now().UTC()
	items := []map[string]any{}

	if role == RoleRequester {
		rows, err := st.PG.QueryContext(ctx, `
			SELECT s.sample_id, s.request_id, s.status, s.serviceability, s.target_laboratory_id,
			       r.requested_at, r.delivery_deadline, r.origin_lat, r.origin_lng
			FROM samples s JOIN collection_requests r ON r.request_id = s.request_id
			WHERE s.requester_id = $1
			ORDER BY r.created_at DESC`, sess.UserID)
		if err != nil {
			return nil, err
		}
		defer rows.Close()
		for rows.Next() {
			var sid, rid, status, svc string
			var lab sql.NullString
			var requested, deadline time.Time
			var lat, lng float64
			if err := rows.Scan(&sid, &rid, &status, &svc, &lab, &requested, &deadline, &lat, &lng); err != nil {
				continue
			}
			if !matchStatus(statusFilter, status, isTerminal(status)) {
				continue
			}
			tl, _ := st.loadTimelineForSample(ctx, sid)
			items = append(items, map[string]any{
				"kind":             "request",
				"sampleId":         sid,
				"requestId":        rid,
				"status":           status,
				"serviceability":   svc,
				"targetLaboratoryId": nullStr(lab),
				"requestedAt":      formatTime(requested),
				"deliveryDeadline": formatTime(deadline),
				"origin":           Coordinate{Latitude: lat, Longitude: lng},
				"timeline":         tl,
				"current":          !isTerminal(status),
			})
		}
		return items, nil
	}

	if isAdminOrDispatcher(role) {
		rows, err := st.PG.QueryContext(ctx, `
			SELECT a.assignment_id, a.sample_id, a.journey_id, a.kind, a.status, a.from_location_id, a.to_location_id,
			       a.worker_id, a.offered_worker_id, a.sequence, s.status
			FROM assignments a JOIN samples s ON s.sample_id = a.sample_id
			ORDER BY a.created_at DESC LIMIT 500`)
		if err != nil {
			return nil, err
		}
		defer rows.Close()
		for rows.Next() {
			item, ok := scanWorkItem(rows, statusFilter)
			if ok {
				sid, _ := item["sampleId"].(string)
				tl, _ := st.loadTimelineForSample(ctx, sid)
				item["timeline"] = tl
				items = append(items, item)
			}
		}
		return items, nil
	}

	rows, err := st.PG.QueryContext(ctx, `
		SELECT a.assignment_id, a.sample_id, a.journey_id, a.kind, a.status, a.from_location_id, a.to_location_id,
		       a.worker_id, a.offered_worker_id, a.sequence, s.status
		FROM assignments a JOIN samples s ON s.sample_id = a.sample_id
		WHERE a.worker_id = $1 OR a.offered_worker_id = $1
		ORDER BY a.created_at DESC`, sess.UserID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	for rows.Next() {
		item, ok := scanWorkItem(rows, statusFilter)
		if !ok {
			continue
		}
		// collection professionals only see collection work they are qualified for
		if role == RoleCollection {
			kind, _ := item["kind"].(string)
			if kind != KindCollection && kind != KindNode {
				// they can also see handoff-related transport they hold
				if kind != KindTransport {
					continue
				}
			}
		}
		if role == RoleDelivery {
			kind, _ := item["kind"].(string)
			if kind != KindTransport {
				continue
			}
		}
		if role == RoleNode {
			kind, _ := item["kind"].(string)
			if kind != KindNode && kind != KindTransport && kind != KindCollection {
				continue
			}
		}
		if role == RoleLab {
			kind, _ := item["kind"].(string)
			if kind != KindLaboratory {
				continue
			}
		}
		sid, _ := item["sampleId"].(string)
		tl, _ := st.loadTimelineForSample(ctx, sid)
		item["timeline"] = tl
		_ = now
		items = append(items, item)
	}
	return items, nil
}

func scanWorkItem(rows *sql.Rows, statusFilter string) (map[string]any, bool) {
	var aid, sid, jid, kind, astatus, sstatus string
	var from, to, worker, offered sql.NullString
	var seq int
	if err := rows.Scan(&aid, &sid, &jid, &kind, &astatus, &from, &to, &worker, &offered, &seq, &sstatus); err != nil {
		return nil, false
	}
	terminal := astatus == AssignCompleted || astatus == AssignCancelled || astatus == AssignDelivered
	if !matchStatus(statusFilter, astatus, terminal) {
		return nil, false
	}
	item := map[string]any{
		"kind":         kind,
		"assignmentId": aid,
		"sampleId":     sid,
		"journeyId":    jid,
		"status":       astatus,
		"sequence":     seq,
		"sampleStatus": sstatus,
		"current":      !terminal,
	}
	if from.Valid {
		item["fromLocationId"] = from.String
	}
	if to.Valid {
		item["toLocationId"] = to.String
	}
	if worker.Valid {
		item["workerId"] = worker.String
	} else if offered.Valid {
		item["offeredWorkerId"] = offered.String
	}
	return item, true
}

func matchStatus(filter, status string, terminal bool) bool {
	if filter == "" {
		return true
	}
	switch filter {
	case "current":
		return !terminal
	case "past", "completed":
		return terminal
	default:
		return status == filter
	}
}

func isTerminal(status string) bool {
	switch status {
	case SampleReceived, SampleCancelled, SampleExpired:
		return true
	}
	return false
}

func (st *Store) handleReadOperations(w http.ResponseWriter, r *http.Request) {
	sess := sessionFrom(r.Context())
	if err := sess.requireAny(RoleAdministrator, RoleDispatcher); err != nil {
		writeAPIError(w, err)
		return
	}
