{"path":"/workspace/backend/ws.go","command":"create","file_text":"package main

import (
	"encoding/json"
	"net/http"
	"strings"
	"sync"
	"time"

	"github.com/gorilla/websocket"
)

var upgrader = websocket.Upgrader{
	CheckOrigin: func(r *http.Request) bool { return true },
	Subprotocols: []string{"lab-logistics-v1"},
}

type wsClient struct {
	conn   *websocket.Conn
	sess   *Session
	send   chan []byte
	since  int64
}

type hub struct {
	mu      sync.Mutex
	clients map[*wsClient]struct{}
}

func newHub() *hub {
	return &hub{clients: map[*wsClient]struct{}{}}
}

func (h *hub) add(c *wsClient) {
	h.mu.Lock()
	h.clients[c] = struct{}{}
	h.mu.Unlock()
}

func (h *hub) remove(c *wsClient) {
	h.mu.Lock()
	delete(h.clients, c)
	h.mu.Unlock()
}

func (st *Store) handleWSEvents(w http.ResponseWriter, r *http.Request, sess *Session, since int64) {
	// extract token from subprotocol if middleware already authenticated via header
	hdr := http.Header{}
	requested := websocket.Subprotocols(r)
	chosen := []string{}
	for _, p := range requested {
		if p == "lab-logistics-v1" || strings.HasPrefix(p, "bearer.") {
			chosen = append(chosen, p)
		}
	}
	if len(chosen) > 0 {
		hdr.Set("Sec-WebSocket-Protocol", strings.Join(chosen, ", "))
	}
	conn, err := upgrader.Upgrade(w, r, hdr)
	if err != nil {
		return
	}
	c := &wsClient{conn: conn, sess: sess, send: make(chan []byte, 32), since: since}
	go c.writePump()
	st.replayAndListen(c)
}

func (c *wsClient) writePump() {
	defer c.conn.Close()
	ticker := time.NewTicker(25 * time.Second)
	defer ticker.Stop()
	for {
		select {
		case msg, ok := <-c.send:
			if !ok {
				return
			}
			_ = c.conn.SetWriteDeadline(time.Now().Add(10 * time.Second))
			if err := c.conn.WriteMessage(websocket.TextMessage, msg); err != nil {
				return
			}
		case <-ticker.C:
			_ = c.conn.SetWriteDeadline(time.Now().Add(10 * time.Second))
			if err := c.conn.WriteMessage(websocket.PingMessage, nil); err != nil {
				return
			}
		}
	}
}

func (st *Store) replayAndListen(c *wsClient) {
	defer close(c.send)
	cursor := c.since
	// initial replay
	st.pushEvents(c, &cursor)
	ticker := time.NewTicker(1 * time.Second)
	defer ticker.Stop()
	for {
		select {
		case <-ticker.C:
			if err := st.pushEvents(c, &cursor); err != nil {
				return
			}
		}
	}
}

func (st *Store) pushEvents(c *wsClient, cursor *int64) error {
	rows, err := st.PG.Query(`
		SELECT id, type, entity_type, entity_id, payload, created_at
		FROM realtime_events
		WHERE id > $1
		  AND (audience_role IS NULL OR audience_role = $2)
		ORDER BY id ASC
		LIMIT 200`, *cursor, c.sess.ActiveRole)
	if err != nil {
		return err
	}
	defer rows.Close()
	for rows.Next() {
		var id int64
		var typ, et, eid string
		var payload []byte
		var created time.Time
		if err := rows.Scan(&id, &typ, &et, &eid, &payload, &created); err != nil {
			continue
		}
		var p map[string]any
		_ = json.Unmarshal(payload, &p)
		if p == nil {
			p = map[string]any{}
		}
		evt := map[string]any{
			"id":         id,
			"type":       typ,
			"entityType": et,
			"entityId":   eid,
			"payload":    p,
			"createdAt":  formatTime(created),
		}
		b, _ := json.Marshal(evt)
		select {
		case c.send <- b:
			*cursor = id
		default:
			return errJSON("internal_error", "slow consumer", 500)
		}
	}
	return nil
}

func (st *Store) wsAuthMiddleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		// allow unauthenticated ready; for /api/events try multiple token sources
		if r.URL.Path == "/api/events" {
			token := bearerFromWS(r, websocket.Subprotocols(r))
			if token == "" {
				// if this is a websocket upgrade without token, reject
				if strings.Contains(strings.ToLower(r.Header.Get("Upgrade")), "websocket") {
					writeErr(w, http.StatusUnauthorized, "unauthorized", "unauthorized")
					return
				}
			} else {
				sess, err := st.loadSession(r.Context(), token)
				if err != nil {
					writeAPIError(w, err)
					return
				}
				ctx := contextWithSession(r, sess)
				next.ServeHTTP(w, r.WithContext(ctx))
				return
			}
		}
		st.authMiddleware(next).ServeHTTP(w, r)
	})
}

func contextWithSession(r *http.Request, sess *Session) (ctx interface{ Done() <-chan struct{} }) {
	return nil
}
"}

