{"path":"/workspace/frontend/src/api.ts","command":"create","file_text":"export const SAMPLE_TYPES = [
  { id: "aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1", name: "Amber" },
  { id: "aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa2", name: "Indigo" },
  { id: "aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa3", name: "Frost" },
  { id: "aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa4", name: "Pulse" },
];

export const ROLES = [
  { id: "administrator", label: "Administrator" },
  { id: "dispatcher", label: "Dispatcher" },
  { id: "requester", label: "Requester" },
  { id: "collection_professional", label: "Certified collection professional" },
  { id: "delivery_partner", label: "Relay courier" },
  { id: "node_handler", label: "Node handler" },
  { id: "laboratory_team", label: "Laboratory intake operator" },
];

export function roleLabel(id: string): string {
  return ROLES.find((r) => r.id === id)?.label ?? id;
}

export type Envelope<T> = { data: T } | { error: string; code: string };

export class ApiError extends Error {
  code: string;
  status: number;
  constructor(code: string, message: string, status: number) {
    super(message);
    this.code = code;
    this.status = status;
  }
}

const TOKEN_KEY = "lab_session_token";

export function getToken(): string | null {
  return localStorage.getItem(TOKEN_KEY);
}

export function setToken(token: string | null) {
  if (token) localStorage.setItem(TOKEN_KEY, token);
  else localStorage.removeItem(TOKEN_KEY);
}

export async function api<T>(
  path: string,
  opts: { method?: string; body?: unknown; auth?: boolean } = {}
): Promise<T> {
  const headers: Record<string, string> = { "Content-Type": "application/json" };
  if (opts.auth !== false) {
    const t = getToken();
    if (t) headers.Authorization = `Bearer ${t}`;
  }
  const res = await fetch(path, {
    method: opts.method ?? (opts.body ? "POST" : "GET"),
    headers,
    body: opts.body !== undefined ? JSON.stringify(opts.body) : undefined,
  });
  const json = (await res.json().catch(() => ({}))) as Envelope<T> & {
    error?: string;
    code?: string;
    status?: string;
  };
  if (!res.ok) {
    throw new ApiError(json.code || "error", json.error || res.statusText, res.status);
  }
  if ("data" in json) return json.data as T;
  return json as T;
}

export function isoNow(): string {
  return new Date().toISOString();
}

export function newIdem(): string {
  return crypto.randomUUID();
}
"}

