  border-radius: 999px;
  padding: 0.1rem 0.5rem;
  font-size: 0.78rem;
  background: #e7eee9;
}
.badge.stale { background: #ffedd5; color: var(--stale); }
.badge.exception { background: #ffe4e6; color: var(--danger); }
.badge.ok { background: #dcfce7; color: var(--ok); }

.map-wrap { height: 420px; border-radius: 12px; overflow: hidden; border: 1px solid var(--line); }
.map-wrap .maplibregl-canvas { outline: none; }

.timeline { list-style: none; padding: 0; margin: 0; }
