import json
with open("/workspace/contracts/openapi.contract.json") as f:
    spec = json.load(f)
schemas = spec["components"]["schemas"]

def dump_schema(name, s, indent=0):
    pref = "  "*indent
    t = s.get("type")
    req = s.get("required")
    extra = []
    if "enum" in s: extra.append("enum="+str(s["enum"]))
    if "format" in s: extra.append("format="+s["format"])
    if "nullable" in s: extra.append("nullable")
    if "additionalProperties" in s:
        ap = s["additionalProperties"]
        extra.append("addProps="+str(ap if not isinstance(ap, dict) else ap.get("type","obj")))
    extras = (" "+" ".join(extra)) if extra else ""
    print(f"{pref}{name}: {t or s.get('$ref','?')}{extras}")
    if req:
        print(f"{pref}  required: {req}")
    props = s.get("properties") or {}
    for pn, ps in props.items():
        dump_schema(pn, ps, indent+1)
    if "items" in s:
        dump_schema("[]", s["items"], indent+1)
    if "allOf" in s:
        for i, sub in enumerate(s["allOf"]):
            dump_schema(f"allOf[{i}]", sub, indent+1)
    if "$ref" in s and not props:
        pass

for name, s in schemas.items():
    print("\n========", name, "========")
    dump_schema(name, s)
