import json
with open("/workspace/contracts/openapi.contract.json") as f:
    spec = json.load(f)

def resolve(ref):
    return ref.split("/")[-1] if isinstance(ref,str) and ref.startswith("#") else ref

def summarize_schema(s, depth=0):
    if not s: return "?"
    if "$ref" in s: return resolve(s["$ref"])
    t = s.get("type","obj")
    if t=="array":
        return f"[{summarize_schema(s.get('items',{}))}]"
    if t=="object" or "properties" in s:
        props = s.get("properties") or {}
        req = set(s.get("required") or [])
        parts=[]
        for k,v in props.items():
            mark = "*" if k in req else ""
            parts.append(f"{k}{mark}:{summarize_schema(v)}")
        extra = ""
        if s.get("additionalProperties"):
            extra = " +addProps"
        return "{" + ", ".join(parts) + extra + "}"
    if "enum" in s:
        return f"{t}{s['enum']}"
    return t

print("=== SUCCESS RESPONSES ===")
for path, methods in spec["paths"].items():
    for method, op in methods.items():
        if method.startswith("x-"): continue
        oid = op.get("operationId")
        # request
        rb = op.get("requestBody",{})
        req_desc = ""
        if rb:
            content = rb.get("content",{}).get("application/json",{})
            sch = content.get("schema",{})
            req_desc = summarize_schema(sch)
        print(f"\n{method.upper()} {path}  [{oid}]")
        if req_desc:
            print(f"  REQ: {req_desc}")
        params = op.get("parameters") or []
        for p in params:
            print(f"  PARAM {p.get('in')} {p.get('name')} required={p.get('required')} schema={p.get('schema')}")
        for code, resp in op.get("responses",{}).items():
            if code.startswith("4") or code.startswith("5"):
                continue
            content = (resp.get("content") or {}).get("application/json",{})
            sch = content.get("schema",{})
            print(f"  {code}: {summarize_schema(sch)}")
